INSERT INTO program_snapshots (snapshot_id, school_id, verified_at) VALUES ('1-20261114', '1', '2026-11-14T07:29:46.522Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('1-20261114', 'f1', 'overview', 'On-campus research MS', 'The on-campus Computer Science M.S. is described as research-focused training in theory, systems, and applications.', 'https://degrees.asu.edu/masters-phd/major/ASU00/ESCOMSCMS/computer-science-ms', 'The on-campus Master of Science program in computer science provides rigorous, research-focused training in theory, systems and applications, preparing you to advance the frontiers of computing', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('1-20261114', 'f2', 'overview', 'Distinct from the MCS', 'The page distinguishes this research M.S. from the industry-oriented Master of Computer Science.', 'https://degrees.asu.edu/masters-phd/major/ASU00/ESCOMSCMS/computer-science-ms', 'Unlike the industry-oriented Master of Computer Science program, the MS program in computer science emphasizes fundamental and applied research.', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('1-20261114', 'f3', 'overview', 'Location and college', 'The degree is listed at the Tempe campus in the Ira A. Fulton Schools of Engineering.', 'https://degrees.asu.edu/masters-phd/major/ASU00/ESCOMSCMS/computer-science-ms', 'Ira A. Fulton Schools of Engineering', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('1-20261114', 'f4', 'overview', '30 credit hours', 'The program is listed as 30 credit hours.', 'https://degrees.asu.edu/masters-phd/major/ASU00/ESCOMSCMS/computer-science-ms', '30 credit hours', '2026-11-14T07:29:46.522Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('1-20261114', 'f5', 'overview', 'Thesis or nonthesis option', 'Students may choose a thesis or nonthesis culminating experience.', 'https://degrees.asu.edu/masters-phd/major/ASU00/ESCOMSCMS/computer-science-ms', 'You may pursue either a thesis or nonthesis option as your culminating experience and can explore advanced topics such as:', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('1-20261114', 'f6', 'overview', 'Advanced topic areas', 'Listed topic areas include AI, cybersecurity, quantum computing, and related areas.', 'https://degrees.asu.edu/masters-phd/major/ASU00/ESCOMSCMS/computer-science-ms', 'including artificial intelligence, cybersecurity, quantum computing and other novel paradigms.', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('1-20261114', 'f7', 'overview', 'STEM-OPT eligible', 'The program page marks the degree as STEM-OPT extension eligible.', 'https://degrees.asu.edu/masters-phd/major/ASU00/ESCOMSCMS/computer-science-ms', 'STEM-OPT extension eligible: Yes', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('1-20261114', 'f8', 'overview', 'STEM-OPT length', 'The page says F-1 students can extend U.S. work experience by 24 months.', 'https://degrees.asu.edu/masters-phd/major/ASU00/ESCOMSCMS/computer-science-ms', 'International students (F1) can extend U.S. work experience by 24 months.', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('1-20261114', 'f9', 'overview', 'Handbook program summary', 'The 2026-2027 M.S. handbook describes a 30-credit program with a computing and AI foundation.', 'https://scai.engineering.asu.edu/wp-content/uploads/sites/31/2026/06/MS-CS-Handbook-2026-27.pdf', 'The Master of Science in Computer Science is a 30-credit hour program that provides students with a comprehensive foundation in computer science and AI', '2026-11-14T07:29:46.522Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('1-20261114', 'f10', 'overview', 'Six concentrations', 'The handbook lists a generic program plus five named concentrations.', 'https://scai.engineering.asu.edu/wp-content/uploads/sites/31/2026/06/MS-CS-Handbook-2026-27.pdf', 'The MS in CS program offers six concentrations:', '2026-11-14T07:29:46.522Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('1-20261114', 'f11', 'requirement', 'Graduate College and Fulton requirements', 'Applicants must meet Graduate College and Ira A. Fulton Schools of Engineering requirements.', 'https://degrees.asu.edu/masters-phd/major/ASU00/ESCOMSCMS/computer-science-ms', 'Applicants must fulfill the requirements of both the Graduate College and the Ira A. Fulton Schools of Engineering.', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('1-20261114', 'f12', 'requirement', 'Prior degree field', 'Applicants need a bachelor''s or master''s in computer science, computer engineering, or a closely related area.', 'https://degrees.asu.edu/masters-phd/major/ASU00/ESCOMSCMS/computer-science-ms', 'Applicants are eligible to apply to the program if they have earned a bachelor''s or master''s degree in computer science, computer engineering or a closely related area from a regionally accredited institution.', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('1-20261114', 'f13', 'requirement', 'GPA 3.25', 'The degree page requires a minimum 3.25 GPA in the last 60 hours of the first bachelor''s degree or in an applicable master''s program.', 'https://degrees.asu.edu/masters-phd/major/ASU00/ESCOMSCMS/computer-science-ms', 'Applicants must have a minimum cumulative GPA of 3.25 (scale is 4.00 = "A") in the last 60 hours of their first bachelor''s degree program or a minimum cumulative GPA of 3.25 (scale is 4.00 = "A") in an applicable master''s degree program.', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('1-20261114', 'f14', 'requirement', 'Application materials', 'Required materials include the graduate application and fee, official transcripts, a statement of purpose, and proof of English proficiency.', 'https://degrees.asu.edu/masters-phd/major/ASU00/ESCOMSCMS/computer-science-ms', 'All applicants must submit:', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('1-20261114', 'f15', 'requirement', 'Calculus prerequisite', 'Students must have completed two semesters or six credit hours of calculus, equivalent to Calculus I and II, before applying.', 'https://degrees.asu.edu/masters-phd/major/ASU00/ESCOMSCMS/computer-science-ms', 'Before applying to the program, students must have completed two semesters or six credit hours of calculus, equivalent to Calculus I and II.', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('1-20261114', 'f16', 'requirement', 'Discrete math recommended on degree page', 'The degree page recommends a discrete math course before admission.', 'https://degrees.asu.edu/masters-phd/major/ASU00/ESCOMSCMS/computer-science-ms', 'Completion of a discrete math course is also recommended before admission.', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('1-20261114', 'f18', 'requirement', 'Deficiency courses', 'Assigned additional undergraduate courses may include CSE 230, CSE 310, CSE 330, and CSE 340 or CSE 355.', 'https://degrees.asu.edu/masters-phd/major/ASU00/ESCOMSCMS/computer-science-ms', 'CSE 230 Computer Organization and Assembly Language Programming', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('1-20261114', 'f19', 'requirement', 'Deficiency grade and timing', 'Assigned additional coursework must be completed with a C or higher within two semesters of admission, according to the degree page.', 'https://degrees.asu.edu/masters-phd/major/ASU00/ESCOMSCMS/computer-science-ms', 'Students assigned any additional coursework upon admission must complete those classes with a grade of "C" (scale is 4.00 = "A") or higher within two semesters of admission.', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('1-20261114', 'f20', 'requirement', 'Letters of recommendation not required', 'The SCAI graduate CS page says letters of recommendation are not required for the Computer Science MCS/MS program.', 'https://scai.engineering.asu.edu/graduate-computer-science/', 'Letters of Recommendation are not required for students applying to the Computer Science MCS/MS program.', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('1-20261114', 'f21', 'requirement', 'GRE not required', 'The 2026-2027 handbook states GRE scores are not required.', 'https://scai.engineering.asu.edu/wp-content/uploads/sites/31/2026/06/MS-CS-Handbook-2026-27.pdf', 'GRE scores are not required.', '2026-11-14T07:29:46.522Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('1-20261114', 'f22', 'requirement', 'Handbook GPA', 'The handbook requires a minimum 3.25 GPA in the last 60 undergraduate credit hours.', 'https://scai.engineering.asu.edu/wp-content/uploads/sites/31/2026/06/MS-CS-Handbook-2026-27.pdf', 'To be considered for the MS program, we require a minimum cumulative GPA of 3.25 in the last 60 credit hours of the undergraduate degree.', '2026-11-14T07:29:46.522Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('1-20261114', 'f23', 'requirement', 'English proficiency', 'The handbook lists English proficiency minimums, including IELTS 6.5.', 'https://scai.engineering.asu.edu/wp-content/uploads/sites/31/2026/06/MS-CS-Handbook-2026-27.pdf', 'Applicants demonstrate proficiency by scoring at least 80 (if taken before January 21, 2026) or 4 (if taken on or after January 21, 2026) on the TOEFL iBT, 6.5 on the IELTS, or 105 on the Duolingo English test.', '2026-11-14T07:29:46.522Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('1-20261114', 'f24', 'course', 'Program options', 'The degree can be completed as a course-based master''s, with a thesis, or with the applied project course CSE 593.', 'https://degrees.asu.edu/masters-phd/major/ASU00/ESCOMSCMS/computer-science-ms', '30 credit hours - course-based master''s, or 30 credit hours and a thesis, or 30 credit hours including the required applied project course (CSE 593)', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('1-20261114', 'f25', 'course', 'Required core areas', 'All options require 9 credit hours in the core areas of applications, foundations, and systems.', 'https://degrees.asu.edu/masters-phd/major/ASU00/ESCOMSCMS/computer-science-ms', 'Required Core Areas (9 credit hours)', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('1-20261114', 'f26', 'course', 'Course-based electives', 'The course-based option includes 21 credit hours of electives.', 'https://degrees.asu.edu/masters-phd/major/ASU00/ESCOMSCMS/computer-science-ms', 'Students in the course-based option take 21 credit hours of electives.', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('1-20261114', 'f27', 'course', 'Thesis electives', 'Thesis students take 15 credit hours of electives.', 'https://degrees.asu.edu/masters-phd/major/ASU00/ESCOMSCMS/computer-science-ms', 'Students in the thesis option take 15 credit hours of electives.', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('1-20261114', 'f28', 'course', 'Applied project electives', 'Applied project students take 18 credit hours of electives.', 'https://degrees.asu.edu/masters-phd/major/ASU00/ESCOMSCMS/computer-science-ms', 'Applied project students take 18 credit hours of electives.', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('1-20261114', 'f29', 'course', 'CSE 593 Applied Project', 'The applied project culminating course is CSE 593 (3 credit hours).', 'https://degrees.asu.edu/masters-phd/major/ASU00/ESCOMSCMS/computer-science-ms', 'CSE 593 Applied Project (3)', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('1-20261114', 'f30', 'course', 'CSE 599 Thesis', 'The thesis culminating course is CSE 599 (6 credit hours).', 'https://degrees.asu.edu/masters-phd/major/ASU00/ESCOMSCMS/computer-science-ms', 'CSE 599 Thesis (6)', '2026-11-14T07:29:46.522Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('1-20261114', 'f31', 'course', '500-level CSE minimum', 'At least 24 of the 30 credit hours must be 500-level CSE courses at ASU.', 'https://degrees.asu.edu/masters-phd/major/ASU00/ESCOMSCMS/computer-science-ms', 'At least 24 of these credit hours must be 500-level CSE courses at ASU.', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('1-20261114', 'f32', 'course', '400-level limit', 'Up to six credit hours of 400-level courses may be applied to the plan of study.', 'https://degrees.asu.edu/masters-phd/major/ASU00/ESCOMSCMS/computer-science-ms', 'Up to six credit hours of 400-level courses may be applied to the plan of study.', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('1-20261114', 'f33', 'course', 'AI concentration courses', 'The handbook lists CSE 571, CSE 575, CSE 576, and CSE 574 as required AI concentration courses.', 'https://scai.engineering.asu.edu/wp-content/uploads/sites/31/2026/06/MS-CS-Handbook-2026-27.pdf', 'CSE 571 Artificial Intelligence (3)', '2026-11-14T07:29:46.522Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('1-20261114', 'f34', 'course', 'Cybersecurity concentration course', 'The handbook requires CSE 543 Information Assurance and Security in the cybersecurity concentration.', 'https://scai.engineering.asu.edu/wp-content/uploads/sites/31/2026/06/MS-CS-Handbook-2026-27.pdf', 'CSE 543: Information Assurance and Security (3)', '2026-11-14T07:29:46.522Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('1-20261114', 'f35', 'deadline', 'Fall priority deadline', 'The degree page lists a Fall in-person priority deadline of 12/01.', 'https://degrees.asu.edu/masters-phd/major/ASU00/ESCOMSCMS/computer-science-ms', '12/01', '2026-11-14T07:29:46.522Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('1-20261114', 'f36', 'deadline', 'Spring priority deadline', 'The degree page lists a Spring in-person priority deadline of 08/01.', 'https://degrees.asu.edu/masters-phd/major/ASU00/ESCOMSCMS/computer-science-ms', '08/01', '2026-11-14T07:29:46.522Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('1-20261114', 'f37', 'deadline', 'Priority deadline meaning', 'Applications completed before the priority deadline receive priority consideration; later applications are reviewed in order and on a space-available basis.', 'https://degrees.asu.edu/masters-phd/major/ASU00/ESCOMSCMS/computer-science-ms', 'A priority deadline means that applications submitted and completed before the priority deadline will receive priority consideration.', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('1-20261114', 'f38', 'deadline', 'Handbook deadlines', 'The 2026-2027 handbook lists December 1 for a Fall start and August 1 for a Spring start.', 'https://scai.engineering.asu.edu/wp-content/uploads/sites/31/2026/06/MS-CS-Handbook-2026-27.pdf', 'December 1 for Fall start', '2026-11-14T07:29:46.522Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('1-20261114', 'f39', 'deadline', 'SCAI deadline table', 'The SCAI graduate CS page lists December 1 for the M.S. or M.C.S. Fall deadline.', 'https://scai.engineering.asu.edu/graduate-computer-science/', 'December 1 (MS or MCS) or', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('1-20261114', 'f40', 'deadline', 'TA application for master''s students', 'The assistantships page says master''s students may apply for Spring 2027 TA, IA, or Grader positions, with a November 7 priority deadline.', 'https://scai.engineering.asu.edu/teaching-research-assistantships-fellowships-awards/', 'The application for spring 2027 TA, IA or Grader positions available for graduate students are now open. Priority deadline is November 7.', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('1-20261114', 'f41', 'deadline', 'TA awards emphasis', 'The same page states that TA positions are awarded to highly qualified PhD students.', 'https://scai.engineering.asu.edu/teaching-research-assistantships-fellowships-awards/', 'TA positions are awarded to highly qualified PhD students.', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('1-20261114', 'f42', 'faculty', 'MS thesis chair list', 'A September 2026 list names faculty currently approved to chair a Computer Science M.S. thesis. The FSE faculty directory page did not return a usable name list without JavaScript.', 'https://docs.google.com/spreadsheets/d/1SpL7-42ZH0EuwMNZf515_hpVd2Jy0_yLz6_PM67ZwLQ/edit?gid=0#gid=0', 'This list below are the faculty who are currently approved to chair a MS thesis for the Computer Science MS programs.', '2026-11-14T07:29:27.152108Z');
