INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('13-20261114', 'f1', 'overview', 'Program and specializations', 'ECE department MSCompE page: specializations include VLSI systems, computer networks, embedded systems, machine learning, and scientific computing.', 'https://electrical.sdsu.edu/programs/graduate/ms-computer-engineering', 'The areas of specialization include (but are not limited to) VLSI Systems, Computer Networks, Embedded Systems, Machine Learning and Scientific Computing.', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('13-20261114', 'f2', 'requirement', '30 units, Plan A or Plan B', 'Each student must complete 30 units under Plan A (thesis) or Plan B (project).', 'https://electrical.sdsu.edu/programs/graduate/ms-computer-engineering', 'Each student must complete 30 units either by selecting Plan A (Thesis) or Plan B (Project).', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('13-20261114', 'f3', 'requirement', '600/700-level unit split', 'Eighteen of the 30 units should be 600- and 700-numbered courses; the remaining 12 may be 500-, 600-, or 700-level department courses.', 'https://electrical.sdsu.edu/programs/graduate/ms-computer-engineering', 'Eighteen of the thirty units should be 600 and 700-numbered courses. The remaining twelve units can be from 500, 600 or 700-level courses offered by the department.', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('13-20261114', 'f4', 'requirement', 'Outside-department course limit', 'No more than two courses may be taken from other College of Engineering or College of Sciences departments, with prior Graduate Advisor approval.', 'https://electrical.sdsu.edu/programs/graduate/ms-computer-engineering', 'No more than two courses can be taken from other departments in the College of Engineering or from the College of Sciences to satisfy these requirements, with the prior approval of the Graduate Advisor.', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('13-20261114', 'f5', 'requirement', 'Minimum 3.0 GPA to complete the degree', 'A minimum average GPA of 3.0 is required to complete the degree.', 'https://electrical.sdsu.edu/programs/graduate/ms-computer-engineering', 'A minimum average GPA of 3.0 is required to successfully complete the degree.', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('13-20261114', 'f6', 'requirement', 'Plan A thesis units', 'Plan A: 21 units of coursework, 6 units of COMPE 797 Research, and 3 units of COMPE 799A Thesis.', 'https://electrical.sdsu.edu/programs/graduate/ms-computer-engineering', 'Students opting for Plan A must complete 21 units of course work (7 courses), 6 units of COMPE 797 "Research" (typically as two 3-unit COMPE 797 “Research”, taken in two different semesters) and 3 units of COMPE 799A "Thesis" under supervision of a full-time ECE faculty.', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('13-20261114', 'f7', 'requirement', 'Plan B project units', 'Plan B: at least 18 units of depth-area courses and 3 units of COMPE 798 as the project.', 'https://electrical.sdsu.edu/programs/graduate/ms-computer-engineering', 'Students opting for Plan B or the Project option are required to pick an area of specialization and complete a minimum of 18 units of “Depth Area Courses” and 3 units of COMPE 798 as the project.', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('13-20261114', 'f8', 'requirement', 'International in-person enrollment', 'International students needing an I-20 must enroll in at least 6 units of in-person instruction per semester and may not take more than 3 units fully online.', 'https://electrical.sdsu.edu/programs/graduate/ms-computer-engineering', 'International Students requiring an I-20 immigration document from SDSU must be enrolled in a minimum of 6 units of in-person course instruction on campus, per semester. International students may not take more than 3 units of fully online course instruction, per semester.', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('13-20261114', 'f9', 'course', 'Computer Networks core options', 'May 11, 2026 course-guidelines PDF, CompE table: Computer Networks core may be COMPE 560, EE 602, or EE 603.', 'https://electrical.sdsu.edu/_resources/files/guidelineforcourses-ece-5-11-26.pdf', 'COMPE 560: Computer Networks', '2026-11-14T07:29:48.542Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('13-20261114', 'f10', 'course', 'Embedded Systems core', 'Course-guidelines PDF: Embedded Systems core is COMPE 571 Embedded Operating Systems.', 'https://electrical.sdsu.edu/_resources/files/guidelineforcourses-ece-5-11-26.pdf', 'COMPE 571: Embedded Operating', '2026-11-14T07:29:48.542Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('13-20261114', 'f11', 'course', 'Machine Learning and Scientific Computing core', 'Course-guidelines PDF: core course is COMPE 510 Machine Learning for Engineering.', 'https://electrical.sdsu.edu/_resources/files/guidelineforcourses-ece-5-11-26.pdf', 'COMPE 510: Machine Learning for Engineering', '2026-11-14T07:29:48.542Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('13-20261114', 'f12', 'course', 'VLSI Systems core', 'Course-guidelines PDF: VLSI Systems core is COMPE 572 VLSI Circuit Design.', 'https://electrical.sdsu.edu/_resources/files/guidelineforcourses-ece-5-11-26.pdf', 'VLSI Systems COMPE 572: VLSI Circuit Design', '2026-11-14T07:29:48.542Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('13-20261114', 'f13', 'course', 'COMPE 560', 'Tentative fall list in the course-guidelines PDF includes COMPE560 Computer and Data Networks.', 'https://electrical.sdsu.edu/_resources/files/guidelineforcourses-ece-5-11-26.pdf', 'COMPE560 Computer and Data Networks', '2026-11-14T07:29:48.542Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('13-20261114', 'f14', 'course', 'COMPE 510', 'Tentative fall list includes COMPE510 Machine Learning for Engineering.', 'https://electrical.sdsu.edu/_resources/files/guidelineforcourses-ece-5-11-26.pdf', 'COMPE510 Machine Learning for Engineering', '2026-11-14T07:29:48.542Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('13-20261114', 'f15', 'course', 'COMPE 571', 'Tentative fall list includes COMPE571 Embedded Operating System.', 'https://electrical.sdsu.edu/_resources/files/guidelineforcourses-ece-5-11-26.pdf', 'COMPE571 Embedded Operating System', '2026-11-14T07:29:48.542Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('13-20261114', 'f16', 'course', 'COMPE 572', 'The PDF lists COMPE572 VLSI Circuit Design in both the fall and spring tentative schedules.', 'https://electrical.sdsu.edu/_resources/files/guidelineforcourses-ece-5-11-26.pdf', 'COMPE572 VLSI Circuit Design', '2026-11-14T07:29:48.542Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('13-20261114', 'f17', 'course', 'COMPE 525', 'Tentative spring list includes COMPE525 Cyber Physical Systems.', 'https://electrical.sdsu.edu/_resources/files/guidelineforcourses-ece-5-11-26.pdf', 'COMPE525 Cyber Physical Systems', '2026-11-14T07:29:48.542Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('13-20261114', 'f18', 'requirement', 'Five 500-level courses allowed for MSCOMPE', 'Course-guidelines instructions: four 500-level courses are accepted for MSEE and five are allowed for MSCOMPE.', 'https://electrical.sdsu.edu/_resources/files/guidelineforcourses-ece-5-11-26.pdf', 'Four 500-level courses are accepted for the MSEE graduate program and five are allowed for the MSCOMPE program.', '2026-11-14T07:29:48.542Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('13-20261114', 'f19', 'requirement', 'Domestic classified admission', 'Department admission page (covers MSEE and MSCompE): domestic classified standing requires a bachelor''s in Electrical or Computer Engineering from an ABET-accredited U.S. program and a 2.85 GPA in the last 60 semester (90 quarter) units of technical coursework.', 'https://electrical.sdsu.edu/programs/graduate/admission', 'Bachelor''s degree in Electrical or Computer Engineering from an ABET accredited engineering program in the USA.', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('13-20261114', 'f20', 'requirement', 'Domestic technical GPA', 'Domestic classified standing also requires a minimum 2.85 GPA in the last 60 semester or 90 quarter units of technical coursework.', 'https://electrical.sdsu.edu/programs/graduate/admission', 'A minimum grade point average of 2.85 (based on 4.0 scale) in the last 60 semester (90 quarter) units of technical course work.', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('13-20261114', 'f21', 'requirement', 'International classified admission', 'International classified standing requires a bachelor''s in Electrical, Electronics, Instrumentation, or Computer Engineering from a recognized program and an equivalent technical GPA of 3.0 or higher.', 'https://electrical.sdsu.edu/programs/graduate/admission', 'An equivalent grade point average of 3.0 (based on 4.0 scale) or higher in all technical course work.', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('13-20261114', 'f22', 'requirement', 'International English score', 'Program minimum TOEFL is 85 or IELTS 6.5, which the page says is higher than the university minimum.', 'https://electrical.sdsu.edu/programs/graduate/admission', 'A minimum TOEFL score of 85 or minimum IELTS score of 6.5. Please note that the minimum TOEFL score required by the program is higher than the minimum required score of the university.', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('13-20261114', 'f23', 'requirement', 'GRE not required (department admissions page)', 'Department admissions page: GRE scores are not required. The 2026–2027 catalog program page could not be fetched (AWS WAF), so a catalog GRE statement could not be compared.', 'https://electrical.sdsu.edu/programs/graduate/admission', 'GRE scores are not required.', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('13-20261114', 'f24', 'requirement', 'Statement of purpose not considered', 'The Electrical Engineering program statement on this shared MSEE & MSCompE admissions page says an SOP is not required and is not used in admission decisions.', 'https://electrical.sdsu.edu/programs/graduate/admission', 'The Electrical Engineering program does not require a Statement of Purpose (SOP) as it is not taken into consideration with making admission decisions. Please do not send an SOP.', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('13-20261114', 'f25', 'requirement', 'Unofficial transcripts and one letter of recommendation', 'Unofficial transcripts and one mandatory LOR are required for both MSEE and MSCompE applicants.', 'https://electrical.sdsu.edu/programs/graduate/admission', 'Unofficial transcripts and one mandatory LOR are required for both the MSEE and MSCompE degree applicants.', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('13-20261114', 'f26', 'deadline', 'Department page Fall 2026 application window', 'Department admissions page: the application window for Fall 2026 is October 1, 2025 to February 1, 2026. This disagrees in cycle/year with the university master''s-degrees page for Fall 2027, quoted separately; both are reported, no winner is chosen.', 'https://electrical.sdsu.edu/programs/graduate/admission', 'The application window for Fall 2026 will be from October 1, 2025 to February 1, 2026.', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('13-20261114', 'f27', 'deadline', 'Department Cal State Apply date for that window', 'Department page: complete the university Cal State Apply application by February 1, 2026.', 'https://electrical.sdsu.edu/programs/graduate/admission', 'Complete the University Online Application via Cal State Apply – Must be completed by February 1, 2026.', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('13-20261114', 'f28', 'deadline', 'Department official documents date', 'Department page: official test scores and transcripts must be received by February 15, 2026.', 'https://electrical.sdsu.edu/programs/graduate/admission', 'Send official test scores and transcripts to Graduate Admissions – Must be received by February 15, 2026.', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('13-20261114', 'f29', 'deadline', 'Scholarship consideration date', 'Department page: applications received after January 15 will not be considered for resident tuition-waiver scholarships.', 'https://electrical.sdsu.edu/programs/graduate/admission', 'Applications received after JANUARY 15th will not be considered for scholarships.', '2026-11-14T07:29:27.152108Z');
