INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('13-20261114', 'f56', 'faculty', 'Amir Alimohammad', 'Profile specialization: Digital VLSI, computational neuroscience, neurotechnology, wireless communication.', 'https://electrical.sdsu.edu/people/amir-alimohammad', 'Specialization Digital VLSI Computational Neuroscience Neurotechnology Wireless Communication', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('13-20261114', 'f57', 'faculty', 'Ashkan Ashrafi', 'Profile specialization: digital signal processing, brain signal processing, estimation theory.', 'https://electrical.sdsu.edu/people/ashkan-ashrafi', 'Specialization Digital Signal Processing Brain Signal Processing Estimation Theory', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('13-20261114', 'f58', 'faculty', 'A. Ege Engin', 'Profile specialization: electromagnetic interference and signal integrity.', 'https://electrical.sdsu.edu/people/a-ege-engin', 'Specialization Electromagnetic Interference Signal Integrity', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('13-20261114', 'f59', 'faculty', 'Ke Huang', 'Profile specialization: VLSI, machine learning, data mining, computer-aided design.', 'https://electrical.sdsu.edu/people/ke-huang', 'Specialization VLSI, Machine Learning Data Mining Computer Aided Design', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('13-20261114', 'f60', 'faculty', 'Chris Mi', 'Profile specialization: power electronics and electric drives, battery management systems, wireless power transfer.', 'https://electrical.sdsu.edu/people/chris-mi', 'Specialization Power Electronics and Electric Drives Battery Management Systems Wireless Power Transfer', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('13-20261114', 'f61', 'faculty', 'Flavio Ponzina', 'Profile: research interests include HW-SW co-design for edge AI, unsupervised/ensemble/distributed learning, energy-efficient systems, and processing in-memory.', 'https://electrical.sdsu.edu/people/flavio-ponzina', 'research interests include HW-SW co-design optimizations for edge AI, unsupervised, ensemble, and distributed learning, energy-efficient systems, and processing in-memory acceleration on emerging memory technologies.', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('13-20261114', 'f62', 'faculty', 'Computer Networks faculty', 'Course-guidelines PDF lists Computer Networks faculty. Department-wide ECE areas, used here because they teach the CompE depth area.', 'https://electrical.sdsu.edu/_resources/files/guidelineforcourses-ece-5-11-26.pdf', 'Computer Networks: Dr. Sunil Kumar, Dr. Yusuf Ozturk, Dr. Christopher Paolini, Dr. Mahasweta Sarkar, Dr. Junfei Xie', '2026-11-14T07:29:48.542Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('13-20261114', 'f63', 'faculty', 'Embedded Systems faculty', 'Course-guidelines PDF lists Embedded Systems faculty.', 'https://electrical.sdsu.edu/_resources/files/guidelineforcourses-ece-5-11-26.pdf', 'Embedded Systems: Dr. Baris Aksanli, Dr. Yusuf Ozturk, Dr. Hakan Toreyin, Dr. Junfei Xie, Dr. Flavio Ponzina', '2026-11-14T07:29:48.542Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('13-20261114', 'f64', 'faculty', 'VLSI Systems faculty', 'Course-guidelines PDF lists VLSI Systems faculty.', 'https://electrical.sdsu.edu/_resources/files/guidelineforcourses-ece-5-11-26.pdf', 'VLSI Systems: Dr. Amir Alimohammad, Dr. Ege Engin, Dr. Ke Huang', '2026-11-14T07:29:48.542Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('13-20261114', 'f65', 'faculty', 'Machine Learning and Scientific Computing faculty', 'Course-guidelines PDF lists Machine Learning and Scientific Computing faculty.', 'https://electrical.sdsu.edu/_resources/files/guidelineforcourses-ece-5-11-26.pdf', 'Machine Learning and Scientific Computing: Dr. Baris Aksanli, Dr. Christopher Paolini, Dr. Junfei Xie', '2026-11-14T07:29:48.542Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('13-20261114', 'f66', 'overview', 'Catalog heading and plan codes', 'The 2026-2027 University Catalog program heading is Computer Engineering, M.S. The page also lists Academic Plan Codes for SDSU Global Campus and SDSU Global Campus-Flex.', 'https://catalog.sdsu.edu/preview_program.php?catoid=12&poid=12546', 'Computer Engineering, M.S. (Major Code: 09094) (Academic Plan Code: 445003MSS) (Academic Plan Code: 445004MSE - SDSU Global Campus) (Academic Plan Code: 445004MSF - SDSU Global Campus-Flex)', '2026-11-14T07:29:48.542Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('13-20261114', 'f67', 'overview', 'Four focus areas', 'The department offers the M.S. in computer engineering with graduate courses in Computer Networks, Embedded Systems, VLSI systems, and Machine Learning/Scientific Computing.', 'https://catalog.sdsu.edu/preview_program.php?catoid=12&poid=12546', 'The program seeks to provide students with core knowledge through graduate courses offered in the four focus areas of Computer Networks, Embedded Systems, Very Large-Scale Integration (VLSI) systems and Machine Learning/ Scientific Computing.', '2026-11-14T07:29:48.542Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('13-20261114', 'f68', 'requirement', 'Admission GPA by student type', 'The catalog asks for a bachelor''s in computer engineering, computer science, electrical engineering, or a closely related area, with a GPA of 3.0 or better for international students and 2.85 for domestic students, on a 4.0 scale. An earlier department-page fact described the 2.85 figure as applying to the last 60 semester units of technical coursework; this catalog sentence does not add that restriction. Both quotes are kept and no winner is chosen.', 'https://catalog.sdsu.edu/preview_program.php?catoid=12&poid=12546', 'Bachelor''s degree in computer engineering, computer science, electrical engineering, or closely related areas with a grade point average of 3.0 or better for international students and a minimum grade point average of 2.85 for domestic students, based on 4.0 scale;', '2026-11-14T07:29:48.542Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('13-20261114', 'f69', 'requirement', 'International English scores', 'International students must have a minimum TOEFL score of 85 or a minimum IELTS score of 6.5.', 'https://catalog.sdsu.edu/preview_program.php?catoid=12&poid=12546', 'A minimum TOEFL score of 85 or a minimum IELTS score of 6.5 for international students;', '2026-11-14T07:29:48.542Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('13-20261114', 'f71', 'requirement', 'One letter of recommendation', 'The catalog admissions list requires one letter of recommendation.', 'https://catalog.sdsu.edu/preview_program.php?catoid=12&poid=12546', 'One letter of recommendation.', '2026-11-14T07:29:48.542Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('13-20261114', 'f73', 'requirement', 'Plan A thesis or Plan B project', 'Students must have a graduate-advisor-approved program of study that meets core, depth, and breadth requirements, and must choose Plan A (Thesis) or Plan B (Project).', 'https://catalog.sdsu.edu/preview_program.php?catoid=12&poid=12546', 'Students must also choose one of two pathways: Plan A (Thesis) or Plan B (Project), for degree completion.', '2026-11-14T07:29:48.542Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('13-20261114', 'f74', 'requirement', 'Depth and breadth areas', 'Students select a depth area and complete approved courses from that area, plus a set of approved courses from other areas in consultation with the graduate advisor. In this paragraph the page names the areas Computer Networks, Embedded operating systems, Machine Learning and Scientific Computing, and VLSI Circuit Design.', 'https://catalog.sdsu.edu/preview_program.php?catoid=12&poid=12546', 'The offered areas are Computer Networks, Embedded operating systems, Machine Learning and Scientific Computing and VLSI Circuit Design.', '2026-11-14T07:29:48.542Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('13-20261114', 'f75', 'requirement', 'Computer Networks core choice', 'For the Computer Networks area, students take one of COMPE 560, E E 602, or E E 603 as core, and at least 3 courses from the Computer Networks depth list.', 'https://catalog.sdsu.edu/preview_program.php?catoid=12&poid=12546', 'Students are required to take one of these courses as core: COMPE 560 - Computer and Data Networks Units: 3 or E E 602 - Stochastic Signals and Systems Units: 3 or E E 603 - Engineering Optimization Units: 3', '2026-11-14T07:29:48.542Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('13-20261114', 'f76', 'requirement', 'Embedded Systems core', 'For Embedded Systems, students take the core course COMPE 571 and at least 3 courses from that area''s depth list.', 'https://catalog.sdsu.edu/preview_program.php?catoid=12&poid=12546', 'Embedded Systems Students are required to take the core course: COMPE 571 - Embedded Operating Systems Units: 3', '2026-11-14T07:29:48.542Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('13-20261114', 'f77', 'requirement', 'Machine Learning and Scientific Computing core', 'For Machine Learning and Scientific Computing, students take the core course COMPE 510 and at least 3 courses from that area''s depth list. The catalog text repeats the word ''the'' in this sentence; the quote is kept as written.', 'https://catalog.sdsu.edu/preview_program.php?catoid=12&poid=12546', 'Machine Learning and Scientific Computing Students are required to take the the core course: COMPE 510 - Machine Learning for Engineers Units: 3', '2026-11-14T07:29:48.542Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('13-20261114', 'f78', 'requirement', 'VLSI Systems core', 'For VLSI Systems, students take the core course COMPE 572 and at least 3 courses from that area''s depth list.', 'https://catalog.sdsu.edu/preview_program.php?catoid=12&poid=12546', 'VLSI Systems Students are required to take the core course: COMPE 572 - VLSI Circuit Design Units: 3', '2026-11-14T07:29:48.542Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('13-20261114', 'f79', 'requirement', 'Depth-course minimum of three', 'In each depth area, the page says students must take at least 3 of the listed depth courses.', 'https://catalog.sdsu.edu/preview_program.php?catoid=12&poid=12546', 'Students must take at least 3 of these courses:', '2026-11-14T07:29:48.542Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('13-20261114', 'f80', 'requirement', 'Plan A thesis units', 'Plan A students take COMPE 797 Research for 6 units and COMPE 799A Thesis for 3 units. Credit for COMPE 797 is given only after COMPE 799A is successfully completed.', 'https://catalog.sdsu.edu/preview_program.php?catoid=12&poid=12546', 'Requirements for Plan A (Thesis) Students are required to take COMPE 797 - Research Units: 3-6 (6 units) Cr/NC/RP COMPE 799A - Thesis Units: 3 (3 units)', '2026-11-14T07:29:48.542Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('13-20261114', 'f81', 'requirement', 'COMPE 797 credit after thesis', 'Credit for COMPE 797 is given only after the student successfully completes COMPE 799A.', 'https://catalog.sdsu.edu/preview_program.php?catoid=12&poid=12546', 'Credit for COMPE 797 will be given only after successfully completing COMPE 799A.', '2026-11-14T07:29:48.542Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('13-20261114', 'f82', 'requirement', 'Plan B project timing and course', 'Plan B students may enroll in COMPE 798 after 18 units, but must do so in the semester immediately after completing 27 units. The project is 3 units of COMPE 798 Special Study, graded Cr/NC/RP. The department determines the evaluation process, enforced by the graduate advisor.', 'https://catalog.sdsu.edu/preview_program.php?catoid=12&poid=12546', 'Students may enroll in the project course, COMPE 798 after completion of 18 units, but must do so in the semester immediately following completion of 27 units.', '2026-11-14T07:29:48.542Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('13-20261114', 'f83', 'requirement', 'Remaining units from depth or breadth', 'Remaining units may come from the selected depth area or from breadth areas; the page then lists approved courses.', 'https://catalog.sdsu.edu/preview_program.php?catoid=12&poid=12546', 'The remaining units can be taken from the selected depth area or from breadth areas. The following courses have been approved:', '2026-11-14T07:29:48.542Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('13-20261114', 'f84', 'course', 'COMPE 560', 'Computer Networks core option (one of three) and a depth/remaining-units course: Computer and Data Networks, 3 units. An earlier guidelines-PDF fact quoted the title as ''Computer Networks''; this catalog page uses ''Computer and Data Networks.'' Both quotes are kept and no winner is chosen.', 'https://catalog.sdsu.edu/preview_program.php?catoid=12&poid=12546', 'COMPE 560 - Computer and Data Networks Units: 3', '2026-11-14T07:29:48.542Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('13-20261114', 'f85', 'course', 'E E 602', 'Computer Networks core option (one of three): Stochastic Signals and Systems, 3 units.', 'https://catalog.sdsu.edu/preview_program.php?catoid=12&poid=12546', 'E E 602 - Stochastic Signals and Systems Units: 3', '2026-11-14T07:29:48.542Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('13-20261114', 'f86', 'course', 'E E 603', 'Computer Networks core option (one of three): Engineering Optimization, 3 units.', 'https://catalog.sdsu.edu/preview_program.php?catoid=12&poid=12546', 'E E 603 - Engineering Optimization Units: 3', '2026-11-14T07:29:48.542Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('13-20261114', 'f87', 'course', 'COMPE 571', 'Required core course for the Embedded Systems area: Embedded Operating Systems, 3 units.', 'https://catalog.sdsu.edu/preview_program.php?catoid=12&poid=12546', 'COMPE 571 - Embedded Operating Systems Units: 3', '2026-11-14T07:29:48.542Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('13-20261114', 'f88', 'course', 'COMPE 510', 'Required core course for Machine Learning and Scientific Computing: Machine Learning for Engineers, 3 units.', 'https://catalog.sdsu.edu/preview_program.php?catoid=12&poid=12546', 'COMPE 510 - Machine Learning for Engineers Units: 3', '2026-11-14T07:29:48.542Z');
