INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('14-20261114', 'f40', 'requirement', 'Classified graduate standing required', 'The page requires classified graduate standing and the basic master''s-degree requirements described elsewhere in the catalog, plus the departmental requirements on this page. This page does not itself spell out those general classified-standing rules.', 'https://catalog.sdsu.edu/preview_program.php?catoid=12&poid=12288', 'In addition to meeting the requirements for classified graduate standing and the basic requirements for the master''s degree as described in Requirements for Master''s Degrees , the student must meet the following departmental requirements:', '2026-11-14T07:30:00.849Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('14-20261114', 'f41', 'requirement', 'Minimum 31 units', 'Students must complete a minimum of 31 units of 500-, 600-, and 700-level courses selected with advisor approval. Earlier department-page facts did not state a unit total.', 'https://catalog.sdsu.edu/preview_program.php?catoid=12&poid=12288', 'Complete a minimum of 31 units of 500-, 600-, and 700-level courses selected with the approval of the advisor.', '2026-11-14T07:30:00.849Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('14-20261114', 'f42', 'requirement', 'CS 798 internship units may be added to the 31', 'One to three units of Computer Science 798 may be added to the 31-unit minimum when used for an internship or practical training.', 'https://catalog.sdsu.edu/preview_program.php?catoid=12&poid=12288', 'One to three units of Computer Science 798 may be added to the 31 minimum units required, when used for an internship or practical training.', '2026-11-14T07:30:00.849Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('14-20261114', 'f43', 'requirement', 'At least 24 units from computer science and mathematics', 'All programs must include at least 24 units chosen from computer science and mathematics.', 'https://catalog.sdsu.edu/preview_program.php?catoid=12&poid=12288', 'All programs must include at least 24 units chosen from computer science and mathematics.', '2026-11-14T07:30:00.849Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('14-20261114', 'f45', 'requirement', 'Plan A thesis GPA of 3.3 (second statement)', 'In the Advancement to Candidacy paragraph, the same page says selecting Plan A is contingent on a minimum 3.3 GPA in courses applicable to the master''s degree and on finding a full-time computer science faculty member to supervise the thesis. The earlier paragraph on this page said 3 GPA. Both sentences are quoted and no winner is chosen.', 'https://catalog.sdsu.edu/preview_program.php?catoid=12&poid=12288', 'Selecting Plan A is contingent upon having a minimum 3.3 GPA in courses applicable to the master''s degree and finding a full-time computer science faculty member to supervise the thesis.', '2026-11-14T07:30:00.849Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('14-20261114', 'f46', 'requirement', 'Advancement to candidacy', 'All students must satisfy the general catalog requirements for advancement to candidacy and must select Plan A (Thesis) or Plan B (Comprehensive Examinations).', 'https://catalog.sdsu.edu/preview_program.php?catoid=12&poid=12288', 'All students must satisfy the general requirements for advancement to candidacy as described in Requirements for Master''s Degrees .', '2026-11-14T07:30:00.849Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('14-20261114', 'f47', 'requirement', 'Required courses 16 units', 'Both Plan A and Plan B require the same 16 units of required courses.', 'https://catalog.sdsu.edu/preview_program.php?catoid=12&poid=12288', 'Required Courses (16 units) The following courses are required for both Plan A and Plan B.', '2026-11-14T07:30:00.849Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('14-20261114', 'f48', 'course', 'CS 514', 'Required 3-unit course for both plans: Database Theory and Implementation.', 'https://catalog.sdsu.edu/preview_program.php?catoid=12&poid=12288', 'CS 514 - Database Theory and Implementation Units: 3', '2026-11-14T07:30:00.849Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('14-20261114', 'f49', 'course', 'CS 549', 'Required 3-unit course for both plans: Machine Learning.', 'https://catalog.sdsu.edu/preview_program.php?catoid=12&poid=12288', 'CS 549 - Machine Learning Units: 3', '2026-11-14T07:30:00.849Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('14-20261114', 'f50', 'course', 'CS 576', 'Required 3-unit course for both plans: Computer Networks and Distributed Systems.', 'https://catalog.sdsu.edu/preview_program.php?catoid=12&poid=12288', 'CS 576 - Computer Networks and Distributed Systems Units: 3', '2026-11-14T07:30:00.849Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('14-20261114', 'f51', 'course', 'CS 577', 'Required 3-unit course for both plans: Principles and Techniques of Data Science.', 'https://catalog.sdsu.edu/preview_program.php?catoid=12&poid=12288', 'CS 577 - Principles and Techniques of Data Science Units: 3', '2026-11-14T07:30:00.849Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('14-20261114', 'f52', 'course', 'CS 601', 'Required 1-unit course for both plans: Graduate Seminar.', 'https://catalog.sdsu.edu/preview_program.php?catoid=12&poid=12288', 'CS 601 - Graduate Seminar Units: 1', '2026-11-14T07:30:00.849Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('14-20261114', 'f53', 'course', 'CS 660', 'Required 3-unit course for both plans: Algorithm Analysis and Design.', 'https://catalog.sdsu.edu/preview_program.php?catoid=12&poid=12288', 'CS 660 - Algorithm Analysis and Design Units: 3', '2026-11-14T07:30:00.849Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('14-20261114', 'f54', 'requirement', 'Plan A elective units', 'Plan A students take 9 units of computer science electives from groups CSY, ISY, and DSC, including at least 6 units of 600- or 700-level computer science courses, excluding CS 790 through CS 799. Three units of 600-level mathematics and statistics from group MST may replace one 600-level computer science course. No more than 3 units of CS 696 and CS 798 can count toward those 9 elective units.', 'https://catalog.sdsu.edu/preview_program.php?catoid=12&poid=12288', '9 units of computer science elective courses from the groups CSY, ISY, and DSC listed below of which at least 6 units must be computer science 600-level or 700-level courses, excluding CS 790 through CS 799.', '2026-11-14T07:30:00.849Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('14-20261114', 'f55', 'requirement', 'Plan A MST substitution and special-topics cap', 'Three units of 600-level mathematics and statistical courses from group MST may replace one 600-level computer science course. No more than 3 units of CS 696 and CS 798 can count toward the 9 Plan A elective units.', 'https://catalog.sdsu.edu/preview_program.php?catoid=12&poid=12288', 'Three units of 600-level mathematics and statistical courses from the group MST listed below may replace one 600-level computer science course. No more than 3 units of CS 696 and CS 798 can be counted towards the 9 units of elective courses.', '2026-11-14T07:30:00.849Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('14-20261114', 'f56', 'requirement', 'Plan A thesis and research units', 'Plan A students must take 3 units of CS797-Research and 3 units of CS799A-Thesis. The thesis requires a report and a defense. CS 799B Thesis or Project Extension, 0 units, may be used if needed.', 'https://catalog.sdsu.edu/preview_program.php?catoid=12&poid=12288', 'Plan A students must take 3 units of CS797-Research and 3 units of CS799A-Thesis. The thesis requires report writing and defense.', '2026-11-14T07:30:00.849Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('14-20261114', 'f57', 'requirement', 'Plan B elective units', 'Plan B students take 15 units from groups CSY, ISY, and DSC, including at least 12 units of 600- or 700-level computer science courses, excluding CS 790 through CS 799. Three units of 600-level mathematics from group MST may replace three units of 600-level computer science. No more than 3 units from the Special Topics Courses section count toward those 12 units.', 'https://catalog.sdsu.edu/preview_program.php?catoid=12&poid=12288', '15 units from groups CSY, ISY, DSC listed below with at least 12 units of which must be computer science 600 or 700-level courses, excluding CS 790 through CS 799.', '2026-11-14T07:30:00.849Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('14-20261114', 'f58', 'requirement', 'Plan B comprehensive exam', 'Plan B students must pass a comprehensive exam covering the required courses and must finish the required courses before taking the exam.', 'https://catalog.sdsu.edu/preview_program.php?catoid=12&poid=12288', 'Plan B students must pass the comprehensive exam covering the required courses. Students must complete the required courses before taking the exam.', '2026-11-14T07:30:00.849Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('14-20261114', 'f59', 'requirement', 'International Plan B progress rule', 'Full-time international students on Plan B who have finished their required coursework must show progress in at least two areas of study each semester until they have completed all but one, either by qualifying examinations or by additional coursework preapproved by the graduate adviser.', 'https://catalog.sdsu.edu/preview_program.php?catoid=12&poid=12288', 'Full-time international students on Plan B who have completed all their required coursework must show progress in at least two areas of study each semester (until they have completed all but one).', '2026-11-14T07:30:00.849Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('14-20261114', 'f60', 'requirement', 'Elective area 600-level unit reminders', 'Electives may come from one or more of the listed areas. In this later paragraph the page says six units must be Computer Sciences 600-level courses for Plan A students, and ''12 Twelve'' units must be Computer Science 600-level courses for Plan B students. The wording is quoted as written.', 'https://catalog.sdsu.edu/preview_program.php?catoid=12&poid=12288', 'Six units must be Computer Sciences 600-level courses (for Plan A students). 12 Twelve units must be Computer Science 600-level courses (for Plan B students).', '2026-11-14T07:30:00.849Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('14-20261114', 'f61', 'course', 'CS 797', 'Plan A Research, 1-3 units; Plan A students must take 3 units.', 'https://catalog.sdsu.edu/preview_program.php?catoid=12&poid=12288', 'CS 797 - Research Units: 1-3', '2026-11-14T07:30:00.849Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('14-20261114', 'f62', 'course', 'CS 799A', 'Plan A Thesis or Project, 3 units.', 'https://catalog.sdsu.edu/preview_program.php?catoid=12&poid=12288', 'CS 799A - Thesis or Project Units: 3', '2026-11-14T07:30:00.849Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('14-20261114', 'f63', 'course', 'CS 799B', 'Thesis or Project Extension, 0 units, listed as ''if needed.''', 'https://catalog.sdsu.edu/preview_program.php?catoid=12&poid=12288', 'CS 799B - Thesis or Project Extension Units: 0 (if needed)', '2026-11-14T07:30:00.849Z');
