INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('2-20261114', 'f1', 'overview', 'Program aim', 'The M.S. is described as deepening hardware and software themes and stressing technical competence and independent work.', 'https://www.cpp.edu/sci/computer-science/prospective-graduate-students/index.shtml', 'The Master of Science program in Computer Science provides an opportunity for students to enhance their understanding of the principal hardware and software themes.', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('2-20261114', 'f2', 'overview', 'Evening classes', 'The FAQ says the program offers evening classes across a wide range of computer science topics.', 'https://www.cpp.edu/sci/computer-science/prospective-graduate-students/frequently-asked-questions.shtml', 'Evening classes with a wide range of topics in computer science', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('2-20261114', 'f3', 'overview', 'Department also plans an online M.S.', 'The department home page announces an Online Master of Science in Computer Science coming up in Fall 2026; that is a different program from this on-campus M.S.', 'https://www.cpp.edu/sci/computer-science/', 'Online Master of Science in Computer Science', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('2-20261114', 'f4', 'requirement', 'Undergraduate CS presumption', 'Admission presumes an undergraduate computer science degree or equivalent core coursework; students without that preparation cannot be admitted.', 'https://www.cpp.edu/sci/computer-science/prospective-graduate-students/admission-requirements.shtml', 'The graduate program is based on the presumption that the student has an undergraduate degree with a major in computer science, or equivalent coursework in the principal computer science and mathematics subjects required', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('2-20261114', 'f5', 'requirement', 'Admission is competitive', 'Meeting minimum requirements does not guarantee admission.', 'https://www.cpp.edu/sci/computer-science/prospective-graduate-students/admission-requirements.shtml', 'These are minimum requirements for the program admission. Admission is competitive and meeting minimum requirement does not guarantee admission to the program.', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('2-20261114', 'f6', 'requirement', 'Unconditional GPA', 'Unconditional admission requires a bachelor''s in CS or a closely related field with a GPA of 3.0 or better in all courses or in the most recent 60 semester units.', 'https://www.cpp.edu/sci/computer-science/prospective-graduate-students/admission-requirements.shtml', 'Applicants seeking unconditional admission must have a bachelor''s degree in Computer Science or closely related field with a GPA of 3.0 or better in all courses or the most recent 60 semester units attempted', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('2-20261114', 'f7', 'requirement', 'Unconditional topic coverage', 'Required background includes calculus, probability and statistics, object-oriented programming, discrete structures, data structures, computer organization, algorithms, computer architecture, operating systems, and software engineering.', 'https://www.cpp.edu/sci/computer-science/prospective-graduate-students/admission-requirements.shtml', '10-12 semester units including Calculus and Probability and Statistics', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('2-20261114', 'f8', 'requirement', 'Conditional admission', 'Applicants with a bachelor''s degree and a GPA above 3.0 who do not meet unconditional requirements may seek conditional admission, with priority given to unconditional admissions first.', 'https://www.cpp.edu/sci/computer-science/prospective-graduate-students/admission-requirements.shtml', 'Applicants who do not meet unconditional admission but have a bachelor''s degree with a GPA above 3.0 may seek conditional admission. However, priority will be given to unconditional admissions first.', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('2-20261114', 'f9', 'requirement', 'International students not conditionally admitted', 'International students who need an I-20 will not be conditionally admitted and must meet all requirements before admission.', 'https://www.cpp.edu/sci/computer-science/prospective-graduate-students/admission-requirements.shtml', 'However, per CSU Admissions and SEVIS Policy, international students attending the University on a visa requiring issuance of an I-20 will NOT be conditionally admitted and must meet all requirements prior to gaining admission to the University.', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('2-20261114', 'f10', 'requirement', 'Conditional students and aid', 'Students in conditional standing do not qualify for federal financial aid until they are in unconditional standing.', 'https://www.cpp.edu/sci/computer-science/prospective-graduate-students/admission-requirements.shtml', 'Students in conditional standing do not qualify for federal financial aid until they are in unconditional standing.', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('2-20261114', 'f11', 'requirement', 'English language requirement', 'Applicants whose native language is not English and whose bachelor''s instruction was not in English must meet IELTS 6.5 or TOEFL 213 computer / 550 paper / 80 internet.', 'https://www.cpp.edu/sci/computer-science/prospective-graduate-students/admission-requirements.shtml', 'must have passed the International English Language Testing System (IELTS) exam with a minimum score of 6.5 or the Test of English as a Foreign Language (TOEFL) exam with a minimum score of 213 on the computer-based, or 550 on the paper-based, or 80 on the Internet-based TOEFL.', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('2-20261114', 'f12', 'requirement', 'Supplemental application form', 'A program supplemental form is required and applications missing it may be declined without review.', 'https://www.cpp.edu/sci/computer-science/prospective-graduate-students/application-procedures.shtml', 'This Program Application form is REQUIRED and applications missing this completed form uploaded to Cal State Mentor site may be declined without review.', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('2-20261114', 'f13', 'requirement', 'SOP, resume, letters, unofficial transcript', 'Applicants must also submit a statement of purpose, resume/CV, two letters of recommendation, and an unofficial PDF transcript on Cal State Apply.', 'https://www.cpp.edu/sci/computer-science/prospective-graduate-students/application-procedures.shtml', 'applicants are REQUIRED to submit a statement of purpose (why applying to CPP CS MS program and how it will help to achieve your career objectives), resume/CV, two letters of recommendation and unoffical pdf transcript on Cal State Apply.', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('2-20261114', 'f14', 'requirement', 'GRE not required', 'The department does not require the GRE, but recommends it if the major GPA does not meet 3.0.', 'https://www.cpp.edu/sci/computer-science/prospective-graduate-students/frequently-asked-questions.shtml', 'The department does not require the GRE. However, it is recommended that you take it if your major GPA does not meet the 3.0 requirement.', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('2-20261114', 'f15', 'requirement', 'GPA to maintain', 'A 3.0 GPA or better must be maintained in all upper-division undergraduate and all graduate courses.', 'https://www.cpp.edu/sci/computer-science/prospective-graduate-students/program-information.shtml', 'A grade point average of 3.0 (B) or better must be maintained in all upper-division undergraduate and all graduate courses.', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('2-20261114', 'f16', 'requirement', 'Transfer unit cap', 'No more than 9 semester units of acceptable graduate credit may be transferred from another graduate institution.', 'https://www.cpp.edu/sci/computer-science/prospective-graduate-students/program-information.shtml', 'No more than 9 semester units of acceptable graduate credit may be transferred from another graduate institution.', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('2-20261114', 'f17', 'requirement', 'Combined transfer limit', 'A total limit of 9 semester units of transfer, Extended University, and/or petitioned units may be included on a master''s contract, with a 7-year time limit.', 'https://www.cpp.edu/sci/computer-science/prospective-graduate-students/program-information.shtml', 'A total limit of 9 semester units of transfer, Extended University, and/or units petitioned for graduate credit may be included on a master''s contract. The stipulated time limit of 7 years applies to all of the above.', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('2-20261114', 'f18', 'course', 'Total units', 'The program requires 30 units in total.', 'https://www.cpp.edu/sci/computer-science/prospective-graduate-students/program-information.shtml', 'TOTAL UNITS REQUIRED: 30 units', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('2-20261114', 'f19', 'course', 'CS 5250', 'Required course: CS 5250 Advanced Computer Architecture (3 units).', 'https://www.cpp.edu/sci/computer-science/prospective-graduate-students/program-information.shtml', 'CS 5250 Advanced Computer Architecture (3 units)', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('2-20261114', 'f20', 'course', 'CS 5300', 'Required course: CS 5300 Advanced Algorithm Design and Analysis.', 'https://www.cpp.edu/sci/computer-science/prospective-graduate-students/program-information.shtml', 'CS 5300 Advanced Algorithm Design and Analysis (3units)', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('2-20261114', 'f21', 'course', 'CS 5800', 'Required course: CS 5800 Advanced Software Engineering (3 units).', 'https://www.cpp.edu/sci/computer-science/prospective-graduate-students/program-information.shtml', 'CS 5800 Advanced Software Engineering (3 units)', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('2-20261114', 'f22', 'course', 'CS 6640', 'Required course: CS 6640 Graduate Seminar (1 unit).', 'https://www.cpp.edu/sci/computer-science/prospective-graduate-students/program-information.shtml', 'CS 6640 Graduate Seminar (1 unit)', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('2-20261114', 'f24', 'course', 'CS 6950 project', 'The master''s project course is CS 6950 (1 unit).', 'https://www.cpp.edu/sci/computer-science/prospective-graduate-students/program-information.shtml', 'CS 6950 Master''s Degree Project (1 unit)', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('2-20261114', 'f27', 'course', '4000-level electives', 'M.S. students may use up to 6 semester units of CS 4000-level electives, with listed exclusions, and may not repeat undergraduate classes already taken.', 'https://www.cpp.edu/sci/computer-science/prospective-graduate-students/program-information.shtml', 'Computer Science MS students can take up to 6 semester units of CS 4000+ levels elective classes to satisfy their elective courses requirement, excluding the following courses: CS 4000, CS 4310, CS 4610, CS 4620, CS 4630, and CS 4800.', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('2-20261114', 'f29', 'course', 'Evening graduate courses', 'Graduate courses traditionally meet in late afternoons and evenings.', 'https://www.cpp.edu/sci/computer-science/prospective-graduate-students/program-information.shtml', 'Graduate courses traditionally meet in late afternoons and evenings.', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('2-20261114', 'f30', 'deadline', 'Fall 2027 on-campus CS M.S.', 'The university graduate deadlines table lists the on-campus Computer Science M.S. Fall 2027 application deadline as 4/1/2027 and the intent-to-enroll deadline as 7/1/2027.', 'https://www.cpp.edu/admissions/graduate/masters-explore.shtml', 'Computer Science', '2026-11-14T07:30:02.983Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('2-20261114', 'f31', 'deadline', 'Spring 2027 on-campus CS M.S.', 'The same table lists the on-campus Computer Science M.S. Spring 2027 application deadline as 10/1/2026 and the intent-to-enroll deadline as 1/12/2027.', 'https://www.cpp.edu/admissions/graduate/masters-explore.shtml', '10/1/2026', '2026-11-14T07:30:02.983Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('2-20261114', 'f32', 'deadline', 'Spring 2027 applications open', 'Spring 2027 applications open July 1, 2026.', 'https://www.cpp.edu/admissions/graduate/masters-explore.shtml', 'Spring 2027 applications open July 1, 2026', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('2-20261114', 'f33', 'deadline', 'Fall 2027 applications open', 'Fall 2027 applications open on August 1, 2026.', 'https://www.cpp.edu/admissions/graduate/masters-explore.shtml', 'Fall 2027 applications open on August 1, 2026', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('2-20261114', 'f34', 'deadline', 'International 5/1 rule', 'If a program''s Fall deadline is after 5/1, international applicants must apply no later than 5/1 for visa timing. The on-campus CS M.S. Fall 2027 deadline is 4/1/2027, which is before that cutoff.', 'https://www.cpp.edu/admissions/graduate/masters-explore.shtml', 'International applicants: For graduate programs that have a Fall application deadline beyond 5/1, international applicants must submit an application no later than 5/1 to ensure sufficient time to obtain a visa.', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('2-20261114', 'f35', 'deadline', 'Applications accepted except summer', 'Applications are accepted semester by semester except Summer, and applicants are encouraged to apply in the initial filing period.', 'https://www.cpp.edu/sci/computer-science/prospective-graduate-students/application-procedures.shtml', 'Applications are accepted semester by semester except Summer.', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('2-20261114', 'f36', 'faculty', 'Graduate coordinator', 'Tingting Chen is listed as Professor and Graduate Coordinator. This is a department-wide faculty listing, not limited to this one program.', 'https://www.cpp.edu/sci/computer-science/faculty-and-staff/permanent-faculty.shtml', 'Professor & Graduate Coordinator', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('2-20261114', 'f37', 'faculty', 'Department chair', 'Amar Raheja is listed as Professor and Chair on the department permanent faculty page.', 'https://www.cpp.edu/sci/computer-science/faculty-and-staff/permanent-faculty.shtml', 'Professor & Chair', '2026-11-14T07:30:02.983Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('2-20261114', 'f38', 'faculty', 'Abdelfattah Amamra research', 'His faculty profile states research interests in cyber security, big data analysis, and machine learning. Department faculty listing, not program-specific.', 'https://www.cpp.edu/faculty/aamamra/index.shtml', 'Dr. Amamra research intersts include Cyber Security, Big Data Analysis, and Machine Learning.', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('2-20261114', 'f39', 'faculty', 'Tingting Chen research', 'Her profile describes current research in data privacy, health informatics, and AI applications in medical systems.', 'https://www.cpp.edu/faculty/tingtingchen/index.shtml', 'My current research interests include data privacy, health informatics and AI applications in medical systems.', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('2-20261114', 'f40', 'faculty', 'Hao Ji research', 'His profile lists large-scale numerical methods, high-performance computing, machine learning, computer vision, and physically-based animation.', 'https://www.cpp.edu/faculty/hji/index.shtml', 'His research interests include Large-scale Numerical Methods, High-performance Computing, Machine Learning, Computer Vision, and Physically-based Animation.', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('2-20261114', 'f41', 'faculty', 'Amar Raheja research', 'His profile lists image processing, computer vision, and machine learning, with interdisciplinary AI applications.', 'https://www.cpp.edu/faculty/raheja/index.shtml', 'My research interests are in the area of image processing, computer vision and machine learning.', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('2-20261114', 'f42', 'faculty', 'Wendy Shi research', 'Her profile, noting she joined in August 2025, describes HCI, computing education, and data science.', 'https://www.cpp.edu/faculty/wendyshi/index.shtml', 'Her research explores the intersection of human-computer interaction, computing education, and data science, with a focus on understanding how technology can support learning, collaboration, and meaningful work.', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('2-20261114', 'f43', 'faculty', 'Yunsheng Wang research', 'His profile lists AIoT, connected and autonomous driving, edge computing, cybersecurity, and social networks.', 'https://www.cpp.edu/faculty/yunshengwang/index.shtml', 'His research interests include Artificial Intelligence of Things (AIoT), connected and autonomous driving, edge computing, cybersecurity, and social networks.', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('2-20261114', 'f44', 'faculty', 'Yu Sun role', 'His profile says he directs the Software Engineering and Mobile Cloud Computing Lab (SoftCom Lab).', 'https://www.cpp.edu/faculty/yusun/index.shtml', 'where he serves as the director of the Software Engineering and Mobile Cloud Computing Lab (SoftCom Lab).', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('2-20261114', 'f45', 'faculty', 'Daisy Tang research', 'Her profile describes doctoral research on multi-robot systems.', 'https://www.cpp.edu/faculty/ftang/index.shtml', 'performing her research on multi-robot systems.', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('2-20261114', 'f46', 'faculty', 'Ericsson Santana Marin research', 'His profile describes research in AI for Threat Intelligence.', 'https://www.cpp.edu/faculty/santanamarin/index.shtml', 'My research focuses on AI for Threat Intelligence (ATI), which develops predictive and adaptive learning models to anticipate emerging threats in adversarial online environments.', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('2-20261114', 'f47', 'faculty', 'Ben Steichen research lab', 'His profile says he leads the hapii lab on human-centered, adaptive, and personalized information interaction.', 'https://www.cpp.edu/faculty/bsteichen/index.shtml', 'Dr. Steichen leads the hapii lab (human-centered, adaptive, and personalized information interaction), which researches novel information access solutions that support each individual person.', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('2-20261114', 'f48', 'faculty', 'Mohammad Husain expertise (listing)', 'The department research-interests page, which is department-wide, lists systems and network security and related areas.', 'https://www.cpp.edu/sci/computer-science/faculty-and-staff/faculty-research-int.shtml', 'Expertise: Systems and network security, digital forensics in embedded systems and cloud computing, smartphone security and social applications, power-aware secure computing', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('2-20261114', 'f49', 'faculty', 'Brianna Posadas expertise (listing)', 'The department research-interests page lists HCI, usable security, accessibility, and applied computing in agriculture, among other areas. No individual cpp.edu/faculty profile page was found (404).', 'https://www.cpp.edu/sci/computer-science/faculty-and-staff/faculty-research-int.shtml', 'Expertise: Human-computer interaction, user-centered design and technology adoption, usable security, accessibility and inclusive design, applied computing in agriculture and other real-world domains, data science and big data analysis, remote sensing (UAVs), computing education', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('2-20261114', 'f50', 'faculty', 'John Korah expertise (listing)', 'The department research-interests page lists parallel and distributed algorithm design, HPC, and related areas.', 'https://www.cpp.edu/sci/computer-science/faculty-and-staff/faculty-research-int.shtml', 'Expertise: Parallel & distributed algorithm design, high performance computing, large & dynamic network analysis, computational social systems, cybersecurity, parallel/distributed information retrieval, modeling & simulation', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('2-20261114', 'f51', 'overview', 'Catalog heading and unit total', 'The 2026-2027 University Catalog program heading is Computer Science, M.S.: 30 units.', 'https://catalog.cpp.edu/preview_program.php?catoid=78&poid=24271', 'Computer Science, M.S.: 30 units', '2026-11-14T07:30:02.983Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('2-20261114', 'f52', 'requirement', 'Major required units', 'The catalog lists 13 units of major required courses. Earlier department-page facts used a required list without CS 5215 and a different elective-unit split; both sources are kept and no winner is chosen.', 'https://catalog.cpp.edu/preview_program.php?catoid=78&poid=24271', 'Major Required: 13 units', '2026-11-14T07:30:02.983Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('2-20261114', 'f53', 'course', 'CS 5215', 'Required 3-unit course on the 2026-2027 catalog page. This course was not in the earlier department-page required list; both sources are kept and no winner is chosen.', 'https://catalog.cpp.edu/preview_program.php?catoid=78&poid=24271', 'CS 5215 - Advanced Machine Learning and AI (3)', '2026-11-14T07:30:02.983Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('2-20261114', 'f54', 'course', 'CS 5250', 'Required 3-unit course on the 2026-2027 catalog page.', 'https://catalog.cpp.edu/preview_program.php?catoid=78&poid=24271', 'CS 5250 - Advanced Computer Architecture (3)', '2026-11-14T07:30:02.983Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('2-20261114', 'f55', 'course', 'CS 5300', 'Required 3-unit course on the 2026-2027 catalog page.', 'https://catalog.cpp.edu/preview_program.php?catoid=78&poid=24271', 'CS 5300 - Advanced Algorithm Design and Analysis (3)', '2026-11-14T07:30:02.983Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('2-20261114', 'f56', 'course', 'CS 5800', 'Required 3-unit course on the 2026-2027 catalog page.', 'https://catalog.cpp.edu/preview_program.php?catoid=78&poid=24271', 'CS 5800 - Advanced Software Engineering (3)', '2026-11-14T07:30:02.983Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('2-20261114', 'f57', 'course', 'CS 6640', 'Required 1-unit course on the 2026-2027 catalog page.', 'https://catalog.cpp.edu/preview_program.php?catoid=78&poid=24271', 'CS 6640 - Graduate Seminar (1)', '2026-11-14T07:30:02.983Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('2-20261114', 'f58', 'requirement', 'Major elective unit range', 'The catalog sets major electives at 12-15 units.', 'https://catalog.cpp.edu/preview_program.php?catoid=78&poid=24271', 'Major Electives: 12-15 units', '2026-11-14T07:30:02.983Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('2-20261114', 'f59', 'requirement', 'Elective units with project vs thesis', 'Students select 15 semester units of electives with the Master''s Degree Project or 12 semester units with the Master''s Degree Thesis. Earlier department-page fact f26 quoted 18 units with the project or 15 with the thesis; both quotes are kept and no winner is chosen.', 'https://catalog.cpp.edu/preview_program.php?catoid=78&poid=24271', 'Select 15 semester units (with Master''s Degree Project) or 12 semester units (with Master''s Degree Thesis)', '2026-11-14T07:30:02.983Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('2-20261114', 'f60', 'requirement', 'Culminating experience unit range and options', 'Students choose Option 1 (2 units) or Option 2 (5 units) for the culminating experience.', 'https://catalog.cpp.edu/preview_program.php?catoid=78&poid=24271', 'Culminating Experience: 2-5 units Choose Option 1 (2 units) or Option 2 (5 units).', '2026-11-14T07:30:02.983Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('2-20261114', 'f61', 'requirement', 'Project vs thesis recommendation', 'The page recommends the MS Project for students seeking industry placement right after graduation, and the MS Thesis for research labs or advanced education such as a Ph.D.', 'https://catalog.cpp.edu/preview_program.php?catoid=78&poid=24271', 'In general, MS Project is recommended for students seeking industry placement right after graduation. MS Thesis option is recommended for students seeking placement at research labs and/or advanced education such as PhD.', '2026-11-14T07:30:02.983Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('2-20261114', 'f62', 'requirement', 'Option 1 project units', 'Option 1 requires 1 unit of CS 6910 Directed Research and 1 unit of CS 6950 Master''s Degree Project. The catalog titles CS 6910 Directed Research; an earlier department-page fact called it Directed Study. Both quotes are kept and no winner is chosen.', 'https://catalog.cpp.edu/preview_program.php?catoid=78&poid=24271', 'Option 1: 2 units CS 6910 - Directed Research (1-3) (1 unit required) CS 6950 - Master''s Degree Project (1) (1 unit required)', '2026-11-14T07:30:02.983Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('2-20261114', 'f63', 'requirement', 'Option 2 thesis units', 'Option 2 requires 2 units of CS 6910 Directed Research and 3 units of CS 6960 Master''s Degree Thesis.', 'https://catalog.cpp.edu/preview_program.php?catoid=78&poid=24271', 'Option 2: 5 units CS 6910 - Directed Research (1-3) (2 units required) CS 6960 - Master''s Degree Thesis (1-3) (3 units required)', '2026-11-14T07:30:02.983Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('2-20261114', 'f64', 'requirement', '4000-level elective cap and excluded courses', 'Up to 6 semester units of CS 4000+ electives may count, excluding CS 4000, 4310, 4610, 4620, 4630, and 4800.', 'https://catalog.cpp.edu/preview_program.php?catoid=78&poid=24271', 'Computer Science MS students can take up to 6 semester units of CS 4000+ level elective classes to satisfy their elective courses requirement, excluding the following courses: CS 4000 , CS 4310 , CS 4610 , CS 4620 , CS 4630 , and CS 4800 .', '2026-11-14T07:30:02.983Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('2-20261114', 'f65', 'requirement', 'No repeat of undergraduate 4000-level classes', 'Those 4000+ classes cannot be ones the student already took as an undergraduate.', 'https://catalog.cpp.edu/preview_program.php?catoid=78&poid=24271', 'However, these 4000+ level classes cannot be classes that a CS MS student already took in their undergraduate curriculum.', '2026-11-14T07:30:02.983Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('2-20261114', 'f66', 'requirement', 'CS 4990 and CS 5990 unit caps', 'A master''s contract may include at most 6 semester units of CS 4990 and 6 semester units of CS 5990.', 'https://catalog.cpp.edu/preview_program.php?catoid=78&poid=24271', 'Therefore, in a master''s contract, a CS MS student can have a maximum of 6 semester units of CS 4990 and 6 semester units of CS 5990 course credits.', '2026-11-14T07:30:02.983Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('2-20261114', 'f67', 'course', 'CS 6910', 'Directed Research, 1-3 units, used in both culminating options.', 'https://catalog.cpp.edu/preview_program.php?catoid=78&poid=24271', 'CS 6910 - Directed Research (1-3)', '2026-11-14T07:30:02.983Z');
