INSERT INTO program_snapshots (snapshot_id, school_id, verified_at) VALUES ('23-20261114', '23', '2026-11-14T07:30:22.655Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('23-20261114', 'f1', 'overview', 'Program description', 'Official M.S. degree page: graduate programs let students study computing areas, conduct specialized research, and make original contributions.', 'https://www.unlv.edu/degree/ms-computer-science', 'Graduate degree programs in the Department of Computer Science provide students the opportunity to study different subject areas of computing science, conduct research in specialized areas, and make original contributions to the field.', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('23-20261114', 'f2', 'overview', 'Available tracks', 'The degree page lists thesis, project, integrated BS-MS, and several exam tracks.', 'https://www.unlv.edu/degree/ms-computer-science', 'Available Options Thesis Track Project Track Integrated BS-MS Track', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('23-20261114', 'f3', 'overview', 'Exam-track options', 'Exam tracks named on the degree page include Foundations and Theory, Cyber Security, AI and Machine Learning, Software Engineering, Data Science and Big Data, Database and Information Retrieval, Graphics and Augmented Reality, and Programming Language and Systems.', 'https://www.unlv.edu/degree/ms-computer-science', 'Exam Track - Foundations and Theory Exam Track - Cyber Security Exam Track - AI and Machine Learning', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('23-20261114', 'f4', 'overview', 'Study areas', 'The degree page lists study areas including algorithms, operating and distributed systems, architecture and networking, computational geometry and robotics, graphics and image processing, programming languages, AI, databases, and software engineering.', 'https://www.unlv.edu/degree/ms-computer-science', 'Our master''s program gives you the opportunity to study different areas, including: Design and analysis of algorithms.', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('23-20261114', 'f5', 'requirement', '30-credit minimum and grade floor', 'Department master''s-requirements page: students must pass at least 30 credits of 600- and 700-level courses with a grade of C or better.', 'https://www.unlv.edu/cs/graduate/masters', 'you must pass at least 30 credits of 600- and 700-level courses with a grade of C or better', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('23-20261114', 'f6', 'requirement', 'At least 24 credits in computer science', 'Department requirements: at least 24 credits must be in computer science.', 'https://www.unlv.edu/cs/graduate/masters', 'At least 24 credits must be in computer science.', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('23-20261114', 'f7', 'requirement', '700-level computer science minimum (department page)', 'Department requirements: at least 18 credits of computer science courses must be at the 700 level. The 2026–27 plans of study also quote a Graduate College 50-percent 700-level rule; both are reported.', 'https://www.unlv.edu/cs/graduate/masters', 'At least 18 credits of computer science courses must be at the 700 level.', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('23-20261114', 'f8', 'requirement', 'Required CS 656, 660, and 677 if not already taken', 'If equivalent courses have not been taken previously, CS 656, 660, and 677 must be included.', 'https://www.unlv.edu/cs/graduate/masters', 'If equivalent courses have not been taken previously, CS 656, 660, and 677 must be included.', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('23-20261114', 'f9', 'requirement', 'Thesis or project credit cap', 'At most six credits of CS 791 (thesis) or three credits of CS 790 (project) can be included.', 'https://www.unlv.edu/cs/graduate/masters', 'At most, six credits of CS 791 (Thesis Option) or three credits of CS 790 (Project Option) can be included.', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('23-20261114', 'f10', 'requirement', '3.0 GPA while in the program', 'A GPA of 3.0 or higher must be maintained; below that, probation, then possible drop if it stays below 3.0 the next regular semester.', 'https://www.unlv.edu/cs/graduate/masters', 'A GPA of 3.0 or higher must be maintained at all times while in the program.', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('23-20261114', 'f11', 'requirement', '2026-27 thesis subplan units', '2026-27 thesis plan of study (header: UNLV Graduate College 2026-2027 Catalog): 24 credits of 600- or 700-level CS courses (up to 3 credits outside CS) plus 6 credits of CS 791; minimum 30 credits.', 'https://www.unlv.edu/sites/default/files/media/document/2026-07/2026-27-MS-CS-Thesis.docx', 'Complete 24 credits of 600- or 700- level Computer Science (CS) courses. Students may complete up to 3 credits outside of CS.', '2026-11-14T07:30:22.655Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('23-20261114', 'f12', 'course', 'CS 791 thesis', '2026-27 thesis plan lists CS 791 for the 6-credit thesis requirement.', 'https://www.unlv.edu/sites/default/files/media/document/2026-07/2026-27-MS-CS-Thesis.docx', 'Thesis – Credits: 6', '2026-11-14T07:30:22.655Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('23-20261114', 'f13', 'requirement', 'Thesis plan graduation minimum', 'Thesis plan: minimum credits required for graduation = 30.', 'https://www.unlv.edu/sites/default/files/media/document/2026-07/2026-27-MS-CS-Thesis.docx', 'Minimum credits required for graduation = 30', '2026-11-14T07:30:22.655Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('23-20261114', 'f14', 'requirement', '2026-27 project subplan units', '2026-27 project plan: 27 credits of 600- or 700-level CS courses (up to 3 outside CS) plus 3 credits of CS 790; minimum 30 credits.', 'https://www.unlv.edu/sites/default/files/media/document/2026-07/2026-27-MS-CS-Project.docx', 'Complete 27 credits of 600- or 700- level Computer Science (CS) courses. Students may complete up to 3 credits outside of CS.', '2026-11-14T07:30:22.655Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('23-20261114', 'f15', 'course', 'CS 790 project', '2026-27 project plan lists CS 790 for the 3-credit project requirement.', 'https://www.unlv.edu/sites/default/files/media/document/2026-07/2026-27-MS-CS-Project.docx', 'Project – Credits: 3', '2026-11-14T07:30:22.655Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('23-20261114', 'f17', 'course', 'Exam track Foundations and Theory required list', '2026-27 Foundations and Theory exam plan: complete 9 credits from CS 656, CS 677, CS 715, CS 758, and CS 789, plus 21 credits of other 600- or 700-level CS courses.', 'https://www.unlv.edu/sites/default/files/media/document/2026-07/2026-27-MS-CS-Exam-Foundations-Theory.docx', 'Required Courses - Credits: 9', '2026-11-14T07:30:22.655Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('23-20261114', 'f18', 'course', 'CS 656 on the Foundations exam list', 'The Foundations and Theory plan lists CS 656 among the required-course options.', 'https://www.unlv.edu/sites/default/files/media/document/2026-07/2026-27-MS-CS-Exam-Foundations-Theory.docx', 'CS 656', '2026-11-14T07:30:22.655Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('23-20261114', 'f19', 'course', 'CS 677 on the Foundations exam list', 'The Foundations and Theory plan lists CS 677 among the required-course options.', 'https://www.unlv.edu/sites/default/files/media/document/2026-07/2026-27-MS-CS-Exam-Foundations-Theory.docx', 'CS 677', '2026-11-14T07:30:22.655Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('23-20261114', 'f20', 'course', 'CS 715 on the Foundations exam list', 'The Foundations and Theory plan lists CS 715 among the required-course options.', 'https://www.unlv.edu/sites/default/files/media/document/2026-07/2026-27-MS-CS-Exam-Foundations-Theory.docx', 'CS 715', '2026-11-14T07:30:22.655Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('23-20261114', 'f21', 'requirement', 'Letters of recommendation (M.S.)', 'Department admissions page, Master of Science in Computer Science section: submit two letters of recommendation.', 'https://www.unlv.edu/cs/admissions', 'Two letters of recommendation concerning your potential for success in the graduate program.', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('23-20261114', 'f22', 'requirement', 'M.S. GPA minimum', 'M.S. admissions: a minimal GPA of 2.75 overall or 3.0 on the last two years of undergraduate work.', 'https://www.unlv.edu/cs/admissions', 'A minimal grade point average (GPA) of 2.75 overall or 3.0 on the last two years of undergraduate work.', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('23-20261114', 'f23', 'requirement', 'Background courses at grade B', 'Evidence that courses equivalent to the department''s basic undergraduate courses have been completed with an average grade of B or better.', 'https://www.unlv.edu/cs/admissions', 'Evidence that courses equivalent to our basic undergraduate courses have been completed with an average grade of B or better.', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('23-20261114', 'f24', 'requirement', 'Bachelor''s degree and transcript', 'Evidence of a bachelor''s degree from an accredited four-year college or university, with an official transcript.', 'https://www.unlv.edu/cs/admissions', 'Evidence that a bachelor''s degree in some field has been earned from an accredited four-year college or university, with an official transcript.', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('23-20261114', 'f25', 'requirement', 'GRE results required (department admissions page)', 'The M.S. section requires results of the Graduate Record Examination. The 2026–2027 catalog program page could not be fetched (AWS WAF), so catalog wording could not be compared.', 'https://www.unlv.edu/cs/admissions', 'Results of the Graduate Record Examination.', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('23-20261114', 'f26', 'deadline', 'Fall and Spring material deadlines', 'Department admissions page: the deadline for receiving all materials is August 1 (Fall) and December 1 (Spring). Graduate assistantship materials may need to arrive earlier.', 'https://www.unlv.edu/cs/admissions', 'The deadline for receiving all materials is August 1 (for Fall) and December 1 (for Spring) admission.', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('23-20261114', 'f27', 'overview', 'Expected master''s timeline (handbook)', 'The August 2026-posted handbook says a master''s is expected to take two years. The handbook''s revision table still lists a March 2020 last revision.', 'https://www.unlv.edu/sites/default/files/media/document/2026-08/MS-PhD-ComputerScience-Handbook.pdf', 'In Computer Science, it is expected to take two years for the Master degree and four to six years for the Ph.D. degree.', '2026-11-14T07:30:22.655Z');
