INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('3-20261109', 'f1', 'overview', 'Program flexibility', 'Catalog: maximum flexibility to concentrate in one or more areas.', 'https://catalog.calpoly.edu/engineering/computer-science-software/computer-science-ms/', 'The program is designed for maximum flexibility to allow students to concentrate  in  one or more areas of study.', '2026-11-06T22:45:09.630Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('3-20261109', 'f2', 'overview', 'Emphasis areas', 'Catalog lists software engineering, AI, networks, graphics, HCI, etc.', 'https://catalog.calpoly.edu/engineering/computer-science-software/computer-science-ms/', 'software engineering, computer architecture, programming languages, theory of computing, operating systems, database systems, distributed computing, computer networks, artificial intelligence, computer graphics, and human computer interaction', '2026-11-06T22:45:09.630Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('3-20261109', 'f3', 'overview', 'Thesis-only option', 'Department: thesis option only; no test-only option.', 'https://csc.calpoly.edu/gr/ms-degree-requirements-2/', 'The CSSE department only offers a thesis option for the MS degree. There is no test-only option.', '2026-11-06T22:45:09.630Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('3-20261109', 'f4', 'overview', 'Unit structure on department page', '20 graduate + 16 electives + 9 thesis units (department page).', 'https://csc.calpoly.edu/gr/ms-degree-requirements-2/', 'The program consists of 20 units of graduate coursework (500-level), 16 units of advisor approved electives (400 or 500-level), and 9 units of thesis.', '2026-11-06T22:45:09.630Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('3-20261109', 'f5', 'overview', 'CSSE graduate programs', 'M.S. and blended B.M.S. in Computer Science.', 'https://csc.calpoly.edu/gr/', 'offers both a M.S. program in Computer Science and B.M.S. program in Computer Science.', '2026-11-06T22:45:09.630Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('3-20261109', 'f6', 'requirement', 'Application materials; no GRE', 'Cal State Apply packet; no GRE.', 'https://catalog.calpoly.edu/engineering/computer-science-software/computer-science-ms/', 'Students apply via Cal State Apply and must submit a transcript, resume, personal statement, and three letters of recommendation. No GRE scores required.', '2026-11-09T20:36:17.845Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('3-20261109', 'f7', 'requirement', 'Prerequisite coursework amount', '~18 semester units expected before starting.', 'https://catalog.calpoly.edu/engineering/computer-science-software/computer-science-ms/', 'equivalent of  18  semester  units of coursework (4-6  courses) from the  list below, prior to starting their MS in Computer Science study.', '2026-11-06T22:45:09.630Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('3-20261109', 'f8', 'requirement', 'GPA CS/SE/CPE', 'Minimum 3.0 including major courses.', 'https://catalog.calpoly.edu/engineering/computer-science-software/computer-science-ms/', 'minimum 3.0 grade point average, including a minimum 3.0 grade point average in major courses', '2026-11-06T22:45:09.630Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('3-20261109', 'f9', 'requirement', 'GPA other fields', 'Minimum 3.25 for other bachelor fields.', 'https://catalog.calpoly.edu/engineering/computer-science-software/computer-science-ms/', 'minimum grade point average of 3.25 for all undergraduate coursework', '2026-11-06T22:45:09.630Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('3-20261109', 'f10', 'requirement', 'Thesis culminating experience', 'MS CS is thesis only.', 'https://catalog.calpoly.edu/engineering/computer-science-software/computer-science-ms/', 'The MS CS program is thesis only.', '2026-11-06T22:45:09.630Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('3-20261109', 'f11', 'requirement', '30 units', 'At least 30 units beyond undergraduate degree.', 'https://catalog.calpoly.edu/engineering/computer-science-software/computer-science-ms/', 'The MS degree requires at least 30 units beyond the undergraduate degree.', '2026-11-06T22:45:09.630Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('3-20261109', 'f12', 'requirement', 'Thesis course sequence', '5590 (3), 5591 (2), 5599 (4).', 'https://csc.calpoly.edu/gr/thesis-coursework/', '9 units of thesis-related courses, including 5590 (3 units), 5591 (2), and 5599 (4).', '2026-11-06T22:45:09.630Z');
