INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('4-20261114', 'f2', 'overview', 'Open to any discipline', 'The program is open to applicants from any discipline and includes a computer science theory foundation plus project-based learning.', 'https://www.csuchico.edu/academics/majors-programs/computer-science-ms.shtml', 'Our program is open to applicants from any discipline and combines a strong foundation in computer science theory with practical, project-based learning opportunities.', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('4-20261114', 'f3', 'overview', 'Catalog welcome statement', 'The 2026-2027 catalog says the M.S. welcomes students from all undergraduate disciplines, including those without a CS background.', 'https://catalog.csuchico.edu/colleges-departments/college-engineering-computer-science-construction-management/computer-science/computer-science-ms/', 'The Master of Science in Computer Science welcomes students from all undergraduate disciplines. The program is designed to accommodate students with and without a computer science background.', '2026-11-14T07:30:23.732Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('4-20261114', 'f4', 'overview', 'Students without a CS background', 'The program page says students from any discipline can enter and can take background courses after enrolling.', 'https://www.csuchico.edu/academics/majors-programs/computer-science-ms.shtml', 'Students from any discipline can enter the program. Students without background courses can take all courses after enrolling.', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('4-20261114', 'f5', 'requirement', '30 units', 'The 2026-2027 catalog lists 30 total units required.', 'https://catalog.csuchico.edu/colleges-departments/college-engineering-computer-science-construction-management/computer-science/computer-science-ms/', 'Total Units Required: 30', '2026-11-14T07:30:23.732Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('4-20261114', 'f6', 'requirement', '600-level minimum', 'At least 18 of the units required for the degree must be in 600-level courses.', 'https://catalog.csuchico.edu/colleges-departments/college-engineering-computer-science-construction-management/computer-science/computer-science-ms/', 'At least 18 of the units required for the degree in 600-level courses.', '2026-11-14T07:30:23.732Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('4-20261114', 'f7', 'requirement', 'Core courses', 'Students complete three graduate core courses (nine units): CSCI 608, CSCI 611, or CSCI 612; plus CSCI 630 and CSCI 650.', 'https://catalog.csuchico.edu/colleges-departments/college-engineering-computer-science-construction-management/computer-science/computer-science-ms/', 'Completion of three graduate core courses (nine units): CSCI 608, CSCI 611, or CSCI 612; CSCI 630 and CSCI 650.', '2026-11-14T07:30:23.732Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('4-20261114', 'f8', 'requirement', 'CSCI 605 excluded', 'CSCI 605 may not be taken to meet program requirements.', 'https://catalog.csuchico.edu/colleges-departments/college-engineering-computer-science-construction-management/computer-science/computer-science-ms/', 'CSCI 605 may not be taken to meet program requirements.', '2026-11-14T07:30:23.732Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('4-20261114', 'f9', 'requirement', 'Most common capstone', 'The most common culminating experience is the capstone course plan.', 'https://catalog.csuchico.edu/colleges-departments/college-engineering-computer-science-construction-management/computer-science/computer-science-ms/', 'The most common culminating experience for master''s students in Computer Science is to demonstrate competency in graduate study by completion of the capstone course using plan (a).', '2026-11-14T07:30:23.732Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('4-20261114', 'f10', 'requirement', 'Capstone course CSCI 693', 'The capstone plan is 30 units of in-class coursework including a passing score in CSCI 693, taken in the last 9 units or last semester, with a maximum of three attempts.', 'https://catalog.csuchico.edu/colleges-departments/college-engineering-computer-science-construction-management/computer-science/computer-science-ms/', 'This plan includes 30 units of in-class coursework, including a passing score in the capstone course CSCI 693. CSCI 693 is to be taken as part of the last 9 units, or during the last semester of the graduate program.', '2026-11-14T07:30:23.732Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('4-20261114', 'f11', 'requirement', 'Project plan qualifications', 'The project plan requires a 3.5 GPA, a faculty nomination, and faculty approval of a project proposal by a 2/3 majority vote.', 'https://catalog.csuchico.edu/colleges-departments/college-engineering-computer-science-construction-management/computer-science/computer-science-ms/', 'maintaining a GPA of 3.5 or above in their post-baccalaureate coursework,', '2026-11-14T07:30:23.732Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('4-20261114', 'f12', 'requirement', '3.0 GPA to remain in program', 'Students must maintain a minimum 3.0 GPA in specified coursework categories.', 'https://catalog.csuchico.edu/colleges-departments/college-engineering-computer-science-construction-management/computer-science/computer-science-ms/', 'Students must maintain a minimum 3.0 grade point average in each of the following three categories: all coursework taken at any accredited institution subsequent to admission to the master''s program;', '2026-11-14T07:30:23.732Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('4-20261114', 'f13', 'requirement', 'C-grade limit', 'No more than two courses with a grade of C may count toward the approved program.', 'https://catalog.csuchico.edu/colleges-departments/college-engineering-computer-science-construction-management/computer-science/computer-science-ms/', 'In addition, students may not count more than two courses in which they receive a grade of C toward the approved program.', '2026-11-14T07:30:23.732Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('4-20261114', 'f14', 'requirement', 'Five-year time limit', 'All degree requirements must be completed within five years, and the department says no course validation or program extensions will be granted.', 'https://catalog.csuchico.edu/colleges-departments/college-engineering-computer-science-construction-management/computer-science/computer-science-ms/', 'Due to the rapid changes in the field of computer science, the Department of Computer Science requires all candidates to complete the program within five years, including projects and theses. No course validation will be allowed and no program extensions will be granted.', '2026-11-14T07:30:23.732Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('4-20261114', 'f16', 'requirement', 'GRE in catalog', 'The 2026-2027 catalog requires a combined GRE verbal and quantitative score of 300 and exempts graduates of an ABET-accredited program in computer science (it does not mention a related discipline).', 'https://catalog.csuchico.edu/colleges-departments/college-engineering-computer-science-construction-management/computer-science/computer-science-ms/', 'Completion of the Graduate Record Examination (GRE) with a combined score of 300 on the verbal and quantitative portions. Graduates of an ABET accredited program in computer science are exempt from this requirement.', '2026-11-14T07:30:23.732Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('4-20261114', 'f17', 'requirement', 'Statement of purpose', 'A statement of purpose is required; the program page lists a resume as optional.', 'https://www.csuchico.edu/academics/majors-programs/computer-science-ms.shtml', 'Statement of purpose, resume (optional)', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('4-20261114', 'f18', 'requirement', 'Letters of reference in catalog', 'The catalog lists submission of two letters of reference among classified-status prerequisites.', 'https://catalog.csuchico.edu/colleges-departments/college-engineering-computer-science-construction-management/computer-science/computer-science-ms/', 'Submission of two letters of reference.', '2026-11-14T07:30:23.732Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('4-20261114', 'f19', 'requirement', 'Prerequisite courses for classified status', 'Classified status requires completion of program prerequisites equivalent to CSCI 111, 211, 217, 311, 370, 430, and 440, which do not count toward the M.S.', 'https://catalog.csuchico.edu/colleges-departments/college-engineering-computer-science-construction-management/computer-science/computer-science-ms/', 'Courses taken for the purpose of advancement to classified status will not be used towards the MS degree.', '2026-11-14T07:30:23.732Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('4-20261114', 'f20', 'requirement', 'CSCI 211 and 311 restriction', 'Only courses from ABET-accredited programs may be used for CSCI 211 and CSCI 311.', 'https://catalog.csuchico.edu/colleges-departments/college-engineering-computer-science-construction-management/computer-science/computer-science-ms/', 'Only courses from ABET accredited programs may be used for CSCI 211 and CSCI 311.', '2026-11-14T07:30:23.732Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('4-20261114', 'f21', 'course', 'CSCI 608', 'Catalog course title: CSCI 608 Data Science for Graduate Studies (3 units).', 'https://catalog.csuchico.edu/colleges-departments/college-engineering-computer-science-construction-management/computer-science/#coursestext', 'CSCI 608 Data Science for Graduate Studies 3 Units', '2026-11-14T07:30:23.732Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('4-20261114', 'f22', 'course', 'CSCI 611', 'Catalog course title: CSCI 611 Applied Machine Learning (3 units).', 'https://catalog.csuchico.edu/colleges-departments/college-engineering-computer-science-construction-management/computer-science/#coursestext', 'CSCI 611 Applied Machine Learning 3 Units', '2026-11-14T07:30:23.732Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('4-20261114', 'f23', 'course', 'CSCI 612', 'Catalog course title: CSCI 612 Applied Computer Vision (3 units).', 'https://catalog.csuchico.edu/colleges-departments/college-engineering-computer-science-construction-management/computer-science/#coursestext', 'CSCI 612 Applied Computer Vision 3 Units', '2026-11-14T07:30:23.732Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('4-20261114', 'f24', 'course', 'CSCI 630', 'Catalog course title: CSCI 630 Software Design and Maintenance (3 units).', 'https://catalog.csuchico.edu/colleges-departments/college-engineering-computer-science-construction-management/computer-science/#coursestext', 'CSCI 630 Software Design and Maintenance 3 Units', '2026-11-14T07:30:23.732Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('4-20261114', 'f25', 'course', 'CSCI 650', 'Catalog course title: CSCI 650 Algorithms and Computability (3 units).', 'https://catalog.csuchico.edu/colleges-departments/college-engineering-computer-science-construction-management/computer-science/#coursestext', 'CSCI 650 Algorithms and Computability 3 Units', '2026-11-14T07:30:23.732Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('4-20261114', 'f26', 'course', 'CSCI 693', 'Catalog course title: CSCI 693 Research Methods in Computer Science (3 units).', 'https://catalog.csuchico.edu/colleges-departments/college-engineering-computer-science-construction-management/computer-science/#coursestext', 'CSCI 693 Research Methods in Computer Science 3 Units', '2026-11-14T07:30:23.732Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('4-20261114', 'f27', 'course', 'CSCI 699P', 'Catalog course title: CSCI 699P Master''s Project (3 units).', 'https://catalog.csuchico.edu/colleges-departments/college-engineering-computer-science-construction-management/computer-science/#coursestext', 'CSCI 699P Master''s Project 3 Units', '2026-11-14T07:30:23.732Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('4-20261114', 'f28', 'course', 'CSCI 699T', 'Catalog course title: CSCI 699T Master''s Thesis (1-6 units).', 'https://catalog.csuchico.edu/colleges-departments/college-engineering-computer-science-construction-management/computer-science/#coursestext', 'CSCI 699T Master''s Thesis 1-6 Units', '2026-11-14T07:30:23.732Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('4-20261114', 'f29', 'course', 'CSCI 605 title', 'CSCI 605 is titled Data Structures and Algorithms for Data Science and may not be used to meet CS M.S. program requirements.', 'https://catalog.csuchico.edu/colleges-departments/college-engineering-computer-science-construction-management/computer-science/#coursestext', 'CSCI 605 Data Structures and Algorithms for Data Science 3 Units', '2026-11-14T07:30:23.732Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('4-20261114', 'f30', 'course', 'Writing proficiency', 'Writing proficiency is demonstrated by passing CSCI 693, CSCI 699P, or CSCI 699T.', 'https://catalog.csuchico.edu/colleges-departments/college-engineering-computer-science-construction-management/computer-science/computer-science-ms/', 'Computer science students will demonstrate their writing competence in the English language by successfully passing CSCI 693, CSCI 699P, or CSCI 699T.', '2026-11-14T07:30:23.732Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('4-20261114', 'f31', 'deadline', 'Fall deadline', 'The program page lists a Fall application deadline of April 1.', 'https://www.csuchico.edu/academics/majors-programs/computer-science-ms.shtml', 'Fall: April 1', '2026-11-14T07:30:23.732Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('4-20261114', 'f32', 'deadline', 'Spring deadline', 'The program page lists a Spring deadline of December 1, and October 1 for international applicants.', 'https://www.csuchico.edu/academics/majors-programs/computer-science-ms.shtml', 'Spring: December 1 (October 1 for international applicants)', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('4-20261114', 'f33', 'deadline', 'Blended program deadlines', 'The blended BS + MS application deadlines are April 1 for fall start and November 1 for spring start; GRE is not required for the blended path.', 'https://catalog.csuchico.edu/colleges-departments/college-engineering-computer-science-construction-management/computer-science/computer-science-ms/', 'Application deadlines: April 1 for fall start, November 1 for spring start.', '2026-11-14T07:30:23.732Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('4-20261114', 'f34', 'faculty', 'Department listing', 'The department faculty-and-staff page is a department-wide listing and does not include research blurbs.', 'https://www.csuchico.edu/academics/college/engineering/departments/computer-science/faculty-staff.shtml', 'Todd Gibson Chair and Professor', '2026-11-14T07:29:27.152108Z');
