INSERT INTO program_snapshots (snapshot_id, school_id, verified_at) VALUES ('5-20261114', '5', '2026-11-14T07:30:25.311Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('5-20261114', 'f1', 'overview', '30-unit program', 'The prospective-students page describes a 30-unit (10-course) M.S., with 5 required courses, 4 electives, and a capstone.', 'https://www.csueastbay.edu/cs/prospective-students/index.html', 'The M.S. Computer Science degree program is 30 units equivalent to 10 courses. Of these, 5 courses (15 units) are required by all students in the program, 4 courses (12 units) are elective courses, and once course is a capstone experience (3-6 units).', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('5-20261114', 'f2', 'overview', 'Three concentrations', 'Applicants select a concentration: Computer Science, Computer Networking, or Artificial Intelligence and Machine Learning.', 'https://www.csueastbay.edu/cs/prospective-students/index.html', 'When you apply you will be asked to select a concentration. We currently have three concentrations that allow specialization in a particular area.', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('5-20261114', 'f3', 'overview', 'Typical load', 'Enrolled M.S. students typically take 1-4 courses (3-12 units) each semester.', 'https://www.csueastbay.edu/cs/prospective-students/index.html', 'Students enrolled in the M.S. graduate program typically take 1-4 courses (3-12 units) each semester, depending on their situation.', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('5-20261114', 'f4', 'requirement', 'Admissions review path', 'Applications go first to the university Office of Admissions and are then forwarded to the Computer Science department for an admit or reject decision.', 'https://www.csueastbay.edu/cs/degrees-programs1/csms.html', 'After the Office of Admissions has completed their review, applications are forwarded to the Computer Science department which makes the decision whether to accept or reject the applicant.', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('5-20261114', 'f5', 'requirement', 'GRE required on start page', 'The assigned start page still says GRE general test scores are required, with preferred percentiles above the 20th verbal and 60th quantitative.', 'https://www.csueastbay.edu/cs/degrees-programs1/csms.html', 'GRE general test scores are required.', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('5-20261114', 'f7', 'requirement', 'Undergraduate GPA 3.0', 'Applicants normally need an undergraduate CS or related degree, a 3.0 GPA in all undergraduate work, and a B or better in listed CS and math courses.', 'https://www.csueastbay.edu/cs/degrees-programs1/csms.html', 'must have a grade point average of 3.0 in all undergraduate work, and must have earned a "B" or better in the Computer Science and Mathematics courses listed below.', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('5-20261114', 'f8', 'requirement', 'Preferred B+ in important courses', 'The start page says the department prefers at least a B+ average in the important courses.', 'https://www.csueastbay.edu/cs/degrees-programs1/csms.html', 'Currently, to be eligible for admission into the M.S. program, we prefer at least a B+ average in the important courses.', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('5-20261114', 'f9', 'requirement', 'International class standing', 'For international applicants, the department looks for students who graduated first class or first class with distinction.', 'https://www.csueastbay.edu/cs/degrees-programs1/csms.html', 'For international applicants, we look for students who have graduated first class or first class with distinction.', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('5-20261114', 'f10', 'requirement', 'Conditional admission', 'Applicants missing some course prerequisites may be admitted as Conditionally Classified if they have completed at least Data Structures and most lower-division prerequisites.', 'https://www.csueastbay.edu/cs/degrees-programs1/csms.html', 'may be admitted to the program at the discretion of the department as a "Conditionally Classified Graduate" student, provided the student''s record clearly demonstrates the capability of completing all the course requirements after admission.', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('5-20261114', 'f11', 'requirement', 'Deficiency grades on start page', 'The start page says course deficiencies or remediation must be completed with grades of B or better before enrolling in graduate CS courses, and those courses do not count toward the master''s degree.', 'https://www.csueastbay.edu/cs/degrees-programs1/csms.html', 'Students must complete any course deficiencies or remediation with grades of "B" or better. Course deficiencies or remediation must be completed before enrolling in graduate Computer Science courses.', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('5-20261114', 'f12', 'requirement', 'Prerequisite grade on first-year page', 'The first-year master''s page says each prerequisite must be passed with a B- or better and does not count toward the M.S. degree.', 'https://www.csueastbay.edu/cs/first-year-masters-students/index.html', 'Each prerequisite must be passed with a B− or better and does not count toward the MS degree.', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('5-20261114', 'f13', 'requirement', 'Most students conditionally classified', 'The first-year page says nearly all incoming students are admitted as Conditionally Classified.', 'https://www.csueastbay.edu/cs/first-year-masters-students/index.html', 'Nearly all incoming students are admitted as Conditionally Classified, which means your admission letter lists prerequisite or remediation courses to complete in addition to your graduate coursework.', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('5-20261114', 'f14', 'requirement', 'Lower-division CS prerequisites', 'Required lower-division equivalents include CS 101, CS 201, CS 211, and CS 221.', 'https://www.csueastbay.edu/cs/degrees-programs1/csms.html', 'CS 101 Computer Science I', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('5-20261114', 'f15', 'requirement', 'Upper-division CS prerequisites', 'Required upper-division equivalents include CS 301, CS 311, CS 321, CS 411, CS 413, and CS 421.', 'https://www.csueastbay.edu/cs/degrees-programs1/csms.html', 'CS 301 Data Structures and Algorithms', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('5-20261114', 'f16', 'requirement', 'Math prerequisites', 'Mathematics admission requirements include MATH 130, MATH 131, MATH 225, and STAT 316.', 'https://www.csueastbay.edu/cs/degrees-programs1/csms.html', 'MATH 130 Calculus I', '2026-11-14T07:30:25.311Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('5-20261114', 'f17', 'requirement', 'Junior college limit', 'Junior-college courses may fulfill lower-division but not upper-division admission prerequisites.', 'https://www.csueastbay.edu/cs/degrees-programs1/csms.html', 'Courses from junior colleges can be used to fulfill lower division admission prerequisites (100 and 200 level) but not upper division admission prerequisites (300 or 400 level.)', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('5-20261114', 'f18', 'requirement', 'Open University note', 'Students who lack enough prerequisites may use Open University; the page says Open University students have last registration priority and no student visa is sponsored by that program.', 'https://www.csueastbay.edu/cs/degrees-programs1/csms.html', 'While Open University allows students to take courses before being accepted to the Master''s program, Open University students have the last registration priority and no student visa are sponsored by the Open University program.', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('5-20261114', 'f19', 'requirement', 'Graduate GPA', 'The first-year page requires 30 units of 600-level coursework, each passed with a C or better, and an overall 3.0 graduate GPA.', 'https://www.csueastbay.edu/cs/first-year-masters-students/index.html', 'The MS in Computer Science requires 30 units of 600-level coursework, each passed with a C or better and an overall 3.0 graduate GPA.', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('5-20261114', 'f20', 'course', 'Five required core courses', 'Every student completes five required core courses: CS 601, CS 611, CS 621, CS 651, and CS 671.', 'https://www.csueastbay.edu/cs/first-year-masters-students/index.html', 'Every student completes five required core courses: CS 601, CS 611, CS 621, CS 651, and CS 671.', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('5-20261114', 'f21', 'course', 'Capstone options', 'The capstone is the Comprehensive Exam (CS 692), a Project (CS 693), or a Thesis (CS 699).', 'https://www.csueastbay.edu/cs/first-year-masters-students/index.html', 'You also complete a concentration and a capstone — the Comprehensive Exam (CS 692), a Project (CS 693), or a Thesis (CS 699).', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('5-20261114', 'f22', 'course', 'CS 601 on 2015 roadmap', 'A department-hosted Computer Science concentration roadmap lists CS 601 Advanced Algorithms (3 units). The form is dated July 31, 2015.', 'https://www.csueastbay.edu/cs/files/docs/ms-cs-cs-concentration-roadmap.pdf', 'CS 601        Advanced Algorithms', '2026-11-14T07:30:25.311Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('5-20261114', 'f23', 'course', 'CS 621 title', 'The same roadmap lists CS 621 Operating System Design.', 'https://www.csueastbay.edu/cs/files/docs/ms-cs-cs-concentration-roadmap.pdf', 'CS 621        Operating System Design', '2026-11-14T07:30:25.311Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('5-20261114', 'f24', 'course', 'CS 651 title', 'The same roadmap lists CS 651 Web Systems.', 'https://www.csueastbay.edu/cs/files/docs/ms-cs-cs-concentration-roadmap.pdf', 'CS 651        Web Systems', '2026-11-14T07:30:25.311Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('5-20261114', 'f25', 'course', 'CS 611 title', 'The same roadmap lists CS 611 Theory of Computation.', 'https://www.csueastbay.edu/cs/files/docs/ms-cs-cs-concentration-roadmap.pdf', 'CS 611             Theory of Computation', '2026-11-14T07:30:25.311Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('5-20261114', 'f26', 'course', 'CS 671 title', 'The same roadmap lists CS 671 Cybersecurity.', 'https://www.csueastbay.edu/cs/files/docs/ms-cs-cs-concentration-roadmap.pdf', 'CS 671             Cybersecurity', '2026-11-14T07:30:25.311Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('5-20261114', 'f27', 'course', 'AI/ML concentration courses', 'The AI/ML roadmap adds CS 661 Advanced Artificial Intelligence, CS 667 Machine Learning, and CS 663 Computer Vision. The form is dated July 31, 2015.', 'https://www.csueastbay.edu/cs/files/docs/ms-cs-aiml-concentration-roadmap.pdf', 'CS 661      Advanced Artificial Intelligence', '2026-11-14T07:30:25.311Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('5-20261114', 'f28', 'course', 'CS 692 eligibility', 'Students must complete the five required courses and have a cumulative GPA of 3.0 before the comprehensive exams, and may not take a required or deficiency course concurrently with CS 692.', 'https://www.csueastbay.edu/cs/graduate-capstone/faq-cs-692-capstone-exam.html', 'and have a cumulative GPA of 3.0.', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('5-20261114', 'f29', 'course', 'CS 692 attempts', 'CS 692 is 3 units, graded CR/NC; students must pass all three exams and have a maximum of three attempts.', 'https://www.csueastbay.edu/cs/graduate-capstone/faq-cs-692-capstone-exam.html', 'CS 692 Capstone Exams is a three (3) unit class. Grading is CR/NC. Students need to pass all three exams to earn a credit for the class.', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('5-20261114', 'f30', 'course', 'CS 693 GPA', 'The capstone project requires a cumulative GPA of 3.5 or higher and a B or better average in the five required courses.', 'https://www.csueastbay.edu/cs/graduate-capstone/cs-693-faq.html', 'In addition, the student must have a cumulative GPA of 3.5 or higher.', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('5-20261114', 'f31', 'course', 'CS 699 GPA', 'The thesis option also requires a graduate and cumulative GPA of 3.5 or higher after the five required courses.', 'https://www.csueastbay.edu/cs/graduate-capstone/cs-699-thesis.html', 'In addition, the student must have a graduate course GPA and cumulative CSUEB GPA of 3.5 or higher.', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('5-20261114', 'f32', 'deadline', 'Pay fees by the deadline', 'The first-year page warns students to pay fees by the deadline, even if waitlisted, or they can be dropped from all classes.', 'https://www.csueastbay.edu/cs/first-year-masters-students/index.html', 'Pay your fees by the deadline — even if you are waitlisted. Unpaid fees can drop you from all classes.', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('5-20261114', 'f33', 'deadline', 'International full-time enrollment', 'F-1 students must enroll in at least 8 units each fall and spring and may take only one fully online course per semester.', 'https://www.csueastbay.edu/cs/first-year-masters-students/index.html', 'International (F-1) students must enroll in at least 8 units each fall and spring.', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('5-20261114', 'f34', 'deadline', 'Financial aid and prerequisites', 'Financial aid is based on degree-applicable 600-level units; prerequisites alone do not establish aid eligibility. The page advises including at least 4 units of 600-level coursework each term.', 'https://www.csueastbay.edu/cs/first-year-masters-students/index.html', 'Because prerequisites are undergraduate courses that do not count toward the degree, enrolling in prerequisites alone — even a full load — does not establish aid eligibility.', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('5-20261114', 'f35', 'faculty', 'Department listing is department-wide', 'The Faculty & Staff page is a department-wide directory, not limited to this M.S. program.', 'https://www.csueastbay.edu/cs/faculty-staff/index.html', 'CSUEB Computer Science Professors', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('5-20261114', 'f36', 'faculty', 'Varick Erickson', 'Listed as Graduate Coordinator on the department faculty page. His directory profile did not include a research blurb in the extracted text.', 'https://www.csueastbay.edu/cs/faculty-staff/index.html', 'Erickson, Varick', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('5-20261114', 'f37', 'faculty', 'Levent Ertaul research', 'His directory profile lists cybersecurity and related research areas. The listing is department-wide.', 'https://www.csueastbay.edu/directory/profiles/cs/ertaullevent.html', 'Research: Cyber Security & Privacy, Cyber War, Hacking Technoligies, Cyber Security Policies, Computer Networks Security, Cryptology, Wireless Security, Cloud Security, International Governance of Cyber Space', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('5-20261114', 'f38', 'faculty', 'Lynne Grewe research', 'Her directory profile lists computer vision, machine learning and AI, and media in social and mobile applications.', 'https://www.csueastbay.edu/directory/profiles/cs/grewelynne.html', 'Computer Vision, Machine Learning & Artificial Intelligence, Media in Social and Mobile Applications', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('5-20261114', 'f39', 'faculty', 'Matt Johnson research', 'His directory profile lists genetic algorithms and artificial intelligence.', 'https://www.csueastbay.edu/directory/profiles/cs/johnsonmatthew.html', 'Research: Genetic Algorithms, Artificial Intelligence', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('5-20261114', 'f40', 'faculty', 'Farzan Roohparvar research', 'His directory profile lists system-on-chip design and related areas. The department page also lists him as Interim Department Chair.', 'https://www.csueastbay.edu/directory/profiles/cs/roohparvarfarzan.html', 'Research: System On Chip (SOC) Design', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('5-20261114', 'f41', 'faculty', 'Yashas Hariprasad research', 'His directory profile describes research at the intersection of AI, cybersecurity, digital forensics, and quantum-safe communication.', 'https://www.csueastbay.edu/directory/profiles/cs/hariprasadyashas.html', 'My expertise lies at the convergence of artificial intelligence, cybersecurity, digital forensics, and quantum-safe communication.', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('5-20261114', 'f42', 'faculty', 'Jiaofei Zhong focus', 'Her directory profile lists a professional focus in extended reality, data engineering, and STEM education.', 'https://www.csueastbay.edu/directory/profiles/cs/zhongfay.html', 'Extended Reality, Data Engineering, STEM Education', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('5-20261114', 'f43', 'faculty', 'Farzan Roohparvar title', 'The department faculty page lists Farzan (Bobby) Roohparvar as Interim Department Chair and Professor.', 'https://www.csueastbay.edu/cs/faculty-staff/index.html', 'Roohparvar, Farzan (Bobby)- Interim Department Chair', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('5-20261114', 'f44', 'faculty', 'Levent Ertaul title', 'The department faculty page lists Levent Ertaul as Department Chair and Professor.', 'https://www.csueastbay.edu/cs/faculty-staff/index.html', 'Ertaul, Levent - Department Chair', '2026-11-14T07:29:27.152108Z');
