INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('6-20261109', 'f4', 'overview', 'Faculty count on homepage', '22 tenured and tenure-track faculty.', 'https://www.fullerton.edu/ecs/cs/', 'With 22 tenured and tenure-track faculty members', '2026-11-06T22:45:10.190Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('6-20261109', 'f60', 'faculty', 'Anand Panangadan', 'Live profile. AI/ML applications.', 'https://www.fullerton.edu/ecs/faculty/apanangadan/', 'applications of artificial intelligence and machine learning', '2026-11-06T22:45:10.190Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('6-20261109', 'f61', 'faculty', 'Anand Panangadan', 'Live profile domains.', 'https://www.fullerton.edu/ecs/faculty/apanangadan/', 'homelessness, transportation, healthcare, earth science, sensor networks, and robotics.', '2026-11-06T22:45:10.190Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('6-20261109', 'f62', 'faculty', 'Paul Salvador Inventado', 'Live profile. EDM/ITS.', 'https://www.fullerton.edu/ecs/faculty/pinventado/', 'educational data mining, machine learning, intelligent tutoring systems, CS education, and STEM education.', '2026-11-06T22:45:10.190Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('6-20261109', 'f63', 'faculty', 'Wenlin Han', 'Live profile. Cybersecurity/blockchain.', 'https://www.fullerton.edu/ecs/faculty/whan/', 'Cybersecurity and Blockchain. Recent interests include DeFi, GameFi, NFTs and Metaverse.', '2026-11-06T22:45:10.190Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('6-20261109', 'f100', 'requirement', '$70 application fee via Cal State Apply', 'ECS college graduate admissions page. Achsah confirms the ECS college page governs admission requirements for the CS program specifically.', 'https://www.fullerton.edu/ecs/academics/graduate-admissions.html', 'pay the $70 application processing fee at Cal State Apply', '2026-11-08T21:51:46.613Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('6-20261109', 'f101', 'requirement', 'No personal statement/SOP required for MS CS', 'ECS college graduate admissions page, which Achsah confirms governs CS-specific requirements. Achsah confirms CSUF does not require a personal statement/SOP for the MS Computer Science program. Also lists letters of recommendation, resumes, and GRE/GMAT as not required.', 'https://www.fullerton.edu/ecs/academics/graduate-admissions.html', 'Please do not submit any of the following items as they are not required for admission: Personal Statements Letter of Recommendations High School Transcripts Certificates of Accomplishments / Trainings Resumes / Work Experience GRE or GMAT Scores', '2026-11-08T21:51:46.613Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('6-20261109', 'f102', 'requirement', 'Official documents and ELP scores before document deadlines', 'ECS college graduate admissions page, which Achsah confirms governs CS-specific requirements.', 'https://www.fullerton.edu/ecs/academics/graduate-admissions.html', 'Official documents and required English Language Proficiency test scores must be submitted and processed before document deadlines.', '2026-11-08T21:51:46.613Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('6-20261109', 'f103', 'requirement', '30 units for ECS master''s programs', 'ECS college graduate admissions page, which Achsah confirms governs CS-specific requirements. Applies to all ECS master''s programs.', 'https://www.fullerton.edu/ecs/academics/graduate-admissions.html', 'All of the master''s programs require 30 units to receive your degree.', '2026-11-08T21:51:46.613Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('6-20261109', 'f104', 'requirement', 'International students must stay full-time', 'ECS college graduate admissions page, which Achsah confirms governs CS-specific requirements.', 'https://www.fullerton.edu/ecs/academics/graduate-admissions.html', 'International students must maintain their full-time student status.', '2026-11-08T21:51:46.613Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('6-20261109', 'f105', 'requirement', 'F-1 applicants and online programs', 'ECS college graduate admissions page, which Achsah confirms governs CS-specific requirements.', 'https://www.fullerton.edu/ecs/academics/graduate-admissions.html', 'Students seeking an F1 Visa are not currently eligible to apply for online graduate programs.', '2026-11-08T21:51:46.613Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('6-20261109', 'f117', 'requirement', 'No application fee waiver', 'ECS college graduate admissions page, which Achsah confirms governs CS-specific requirements.', 'https://www.fullerton.edu/ecs/academics/graduate-admissions.html', 'An application fee waiver is not available.', '2026-11-08T21:51:46.613Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('6-20261109', 'f106', 'requirement', 'University minimum GPA 2.5', 'Office of Graduate Studies, institution-wide baseline requirement that applies alongside the CS-specific list above (not in conflict; general eligibility floor, not a materials requirement).', 'https://www.fullerton.edu/graduate/apply/', 'University requirements include having a minimum GPA of 2.5 (cumulative or last 60 semester GPA units), a bachelor’s degree from an institutionally accredited college or university, and good standing with the last attended institution.', '2026-11-08T21:51:46.613Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('6-20261109', 'f107', 'requirement', '4-year degree or equivalent', 'Office of Graduate Studies, institution-wide baseline requirement that applies alongside the CS-specific list above. 3-year degrees may use a WES/IEE equivalency report.', 'https://www.fullerton.edu/graduate/apply/', 'CSUF will only accept 4-year degrees or equivalent.', '2026-11-08T21:51:46.613Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('6-20261109', 'f108', 'requirement', 'English Language Proficiency test for non-US attendees', 'Office of Graduate Studies, institution-wide baseline requirement that applies alongside the CS-specific list above. Duolingo accepted.', 'https://www.fullerton.edu/graduate/apply/', 'Students who attended a university outside of the United States and do not qualify for a waiver must take an English Language Proficiency (ELP) test', '2026-11-08T21:51:46.613Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('6-20261109', 'f109', 'requirement', 'One program per campus per semester', 'Office of Graduate Studies, institution-wide baseline requirement that applies alongside the CS-specific list above.', 'https://www.fullerton.edu/graduate/apply/', 'You can only apply to one program per campus, for a given semester.', '2026-11-08T21:51:46.613Z');
