INSERT INTO program_snapshots (snapshot_id, school_id, verified_at) VALUES ('7-20261114', '7', '2026-11-14T07:30:26.393Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('7-20261114', 'f1', 'overview', 'Online MSE purpose', 'The about page describes the online M.S. in Software Engineering as preparation for careers as software engineers and software project managers.', 'https://www.fullerton.edu/ecs/mse/about/', 'The Master of Science in Software Engineering (MSE) is an online program that prepares individuals for careers as software engineers and software project managers in industry and government agencies.', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('7-20261114', 'f2', 'overview', 'Process-oriented curriculum', 'The curriculum is described as a process-oriented approach grounded in software engineering research, theory, principles, and practice, including CMMI, ISO, agile, Scrum, XP, and architecture/design patterns.', 'https://www.fullerton.edu/ecs/mse/about/', 'The program emphasizes a comprehensive and thorough process-oriented approach to software development, and its curriculum is fundamentally grounded in software engineering research, theory, principles, and practice', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('7-20261114', 'f3', 'overview', 'Designed for working professionals', 'The program is designed for professionals working in computer science who want graduate education in software engineering.', 'https://www.fullerton.edu/ecs/mse/about/', 'The program is designed for professionals working in the field of computer science who wish to further their skills and pursue graduate level education in Software Engineering.', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('7-20261114', 'f4', 'overview', 'Culminating practicum project', 'The culminating activity is a practicum project on a large-scale software project, not a thesis.', 'https://www.fullerton.edu/ecs/mse/about/', 'The culminating activity of the M.S. will be a practicum project where each student applies his or her knowledge and skills to a large-scale software project.', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('7-20261114', 'f5', 'overview', '100% online asynchronous', 'The home page states that all courses are 100% online with asynchronous delivery.', 'https://www.fullerton.edu/ecs/mse/', 'All courses 100% online', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('7-20261114', 'f6', 'overview', 'No I-20 for this program', 'The FAQ says an I-20 cannot be issued because the program is offered entirely online.', 'https://www.fullerton.edu/ecs/mse/faq.php', 'An I-20 cannot be issued for the MSE program, since it is offered entirely online. U.S. immigration policy prohibits the student visa for entirely online programs.', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('7-20261114', 'f7', 'overview', 'Distinct from on-campus AMSE', 'CSUF also offers an on-campus Accelerated M.S. in Software Engineering (AMSE), operated by Extension and International Programs; the online MSE is operated by the Computer Science department.', 'https://www.fullerton.edu/ecs/mse/faq.php', 'CSUF offers two software engineering programs: the online MSE program and the on-campus Accelerated Master of Science in Software Engineering (AMSE) program.', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('7-20261114', 'f8', 'overview', 'Degree title has no ''Online''', 'The FAQ says the word Online will not appear on the diploma; the degree is Master of Science in Software Engineering.', 'https://www.fullerton.edu/ecs/mse/faq.php', 'No. Although this is a fully online program, the degree itself is a "Master of Science in Software Engineering." The word "Online" will not appear on your degree.', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('7-20261114', 'f9', 'overview', 'Program length', 'The FAQ says the online MSE regularly takes 22 months; AMSE takes 17 months.', 'https://www.fullerton.edu/ecs/mse/faq.php', 'Regularly MSE takes 22 months, while AMSE takes 17 months to complete.', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('7-20261114', 'f10', 'requirement', 'University GPA', 'Applicants need an acceptable baccalaureate degree with a minimum cumulative GPA of 2.5 for Computer Science undergraduates or 3.0 for other degree holders.', 'https://www.fullerton.edu/ecs/mse/requirements/', 'The applicant must have completed four-year college course of study and hold an acceptable baccalaureate degree with a minimum/cumulative grade point average of 2.5 for applicants having an undergraduate degree in Computer Science or 3.0 for other degree holders.', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('7-20261114', 'f11', 'requirement', 'Transcripts', 'An official transcript is required from each university or college attended.', 'https://www.fullerton.edu/ecs/mse/requirements/', 'An official transcript is required from each university or college you have attended.', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('7-20261114', 'f12', 'requirement', 'International English scores', 'International students must meet a minimum of 550 paper or 80 TOEFL, 6.5 Academic IELTS, or 58 PTE.', 'https://www.fullerton.edu/ecs/mse/requirements/', 'For international students: a minimum score of 550 (paper) or 80 in TOEFL or 6.5 Academic in IELTS or 58 in PTE.', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('7-20261114', 'f13', 'requirement', 'Software engineering background', 'Applicants should have taken an introductory software engineering course equivalent to CPSC 362 or have work experience in software development.', 'https://www.fullerton.edu/ecs/mse/requirements/', 'The applicant should have taken an Introductory Software Engineering course (equivalent with CPSC 362 at CSUF) or should have work experience in software development.', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('7-20261114', 'f14', 'requirement', 'Work-experience alternative', 'The FAQ says at least one year of software development experience is expected if the applicant has not completed CPSC 362 or an equivalent course, and a resume should be emailed to the program.', 'https://www.fullerton.edu/ecs/mse/faq.php', 'To apply, at least one year of experience in software development is expected.', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('7-20261114', 'f15', 'requirement', 'GRE not required', 'The FAQ says the GRE is not required.', 'https://www.fullerton.edu/ecs/mse/faq.php', 'No, we do not require the GRE.', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('7-20261114', 'f16', 'requirement', 'TOEFL/IELTS when needed', 'TOEFL/IELTS is needed if the applicant has not earned at least 72 college-level units in the U.S. or another majority English-speaking country.', 'https://www.fullerton.edu/ecs/mse/faq.php', 'Yes, if you have not earned at least 72 college-level units in the U.S. or another majority English-speaking country. Residency/citizenship is irrelevant to this requirement.', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('7-20261114', 'f17', 'requirement', 'No exit exam or thesis', 'There is no exit exam; students complete a terminal project in CPSC 597, and there is no thesis option.', 'https://www.fullerton.edu/ecs/mse/faq.php', 'No, there is no exit exam. Students are required to complete a significant terminal project as part of the curriculum (CPSC 597). There is no thesis option.', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('7-20261114', 'f19', 'requirement', 'No program-level scholarship', 'The FAQ says there is no scholarship at the program level and points to university financial aid.', 'https://www.fullerton.edu/ecs/mse/faq.php', 'There is no scholarship at the program level. However, you may check the university Financial Aid website for available funding opportunities.', '2026-11-14T07:29:27.152108Z');
