INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('7-20261114', 'f28', 'course', 'CPSC 589', 'CPSC 589 Seminar in Computer Science is the online version offered to MSE students only, used to survey related work and build a project proposal.', 'https://www.fullerton.edu/ecs/mse/programs/courses.php', 'The online version of CPSC 589, offered to MSE students only. Prepare for the graduate project - survey related work and build a project proposal.', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('7-20261114', 'f29', 'course', 'CPSC 597', 'CPSC 597 Project is the online version offered to MSE students only, used to perform the graduate project proposed in CPSC 589.', 'https://www.fullerton.edu/ecs/mse/programs/courses.php', 'The on-line version of CPSC 597, offered to MSE students only. Perform a graduate project as you proposed in CPSC 589 and write a project report.', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('7-20261114', 'f30', 'course', 'First-year fall schedule', 'First year Fall courses are CPSC 541 and CPSC 544, totaling 6 units.', 'https://www.fullerton.edu/ecs/mse/programs/courses.php', 'CPSC 541', '2026-11-14T07:30:26.393Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('7-20261114', 'f31', 'course', 'Schedule by semester', 'The courses page includes a term-by-term schedule with 6 units each term through second-year Spring.', 'https://www.fullerton.edu/ecs/mse/programs/courses.php', 'Schedule by Semester', '2026-11-14T07:29:27.152108Z');
