INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('7-20261114', 'f43', 'faculty', 'Bin Cong', 'Program Coordinator and Professor of Computer Science; expertise listed includes CMMI and software architecture and engineering. This is a program faculty listing for the online MSE.', 'https://www.fullerton.edu/ecs/mse/faculty/index.php', 'Bin Cong, Ph.D.', '2026-11-14T07:30:26.393Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('7-20261114', 'f44', 'faculty', 'Bin Cong expertise', 'His listed expertise includes SEI CMM/CMMI roles, internet and enterprise computing, and software architecture and engineering.', 'https://www.fullerton.edu/ecs/mse/faculty/index.php', 'SEI Authorized CMM Lead Assessor', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('7-20261114', 'f45', 'faculty', 'Ning Chen', 'Professor of Computer Science; expertise includes embedded systems, software testing, and enterprise software architecture.', 'https://www.fullerton.edu/ecs/mse/faculty/index.php', 'Ning Chen, Ph.D.', '2026-11-14T07:30:26.393Z');
