INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('7-20261114', 'f47', 'faculty', 'James Choi', 'Professor of Computer Science; expertise includes software development methodology, reverse engineering, and configuration management.', 'https://www.fullerton.edu/ecs/mse/faculty/index.php', 'James Choi, Ph.D.', '2026-11-14T07:30:26.393Z');
