INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('7-20261114', 'f49', 'faculty', 'Christopher Ryu', 'Professor of Computer Science; expertise includes software design and architecture plus machine learning and AI.', 'https://www.fullerton.edu/ecs/mse/faculty/index.php', 'Christopher Ryu, Ph.D.', '2026-11-14T07:29:27.152108Z');
