INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('7-20261114', 'f51', 'faculty', 'Chang-Hyun Jo', 'Professor of Computer Science; expertise includes agile software process and CMMI/ISO and object-oriented and agent-oriented software engineering.', 'https://www.fullerton.edu/ecs/mse/faculty/index.php', 'Chang-Hyun Jo, Ph.D.', '2026-11-14T07:29:27.152108Z');
