INSERT INTO program_snapshots (snapshot_id, school_id, verified_at) VALUES ('8-20261114', '8', '2026-11-14T07:30:30.817Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('8-20261114', 'f1', 'overview', 'Program audience and curriculum focus', 'Program page: the M.S. is tailored to working professionals and is described as offering a current computing curriculum.', 'https://www.csulb.edu/hung-family-college-of-engineering/master-of-science-computer-science', 'Tailored to the schedules of working professionals, the CSULB Master of Science in Computer Science program offers the most relevant and up-to-date curriculum to meet the demands of the rapidly changing world of computing.', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('8-20261114', 'f2', 'overview', 'Advanced study areas', 'Program page: the M.S. provides advanced study in software development and engineering, networking, operating systems, distributed computing, AI, and algorithm analysis.', 'https://www.csulb.edu/hung-family-college-of-engineering/master-of-science-computer-science', 'The M.S. in Computer Science provides advanced study in software development and engineering, networking, operating systems, distributed computing, artificial intelligence, and analysis of algorithms.', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('8-20261114', 'f3', 'overview', 'Concentrations', 'Students can pursue concentrations in Advanced Systems or Software Development.', 'https://www.csulb.edu/hung-family-college-of-engineering/master-of-science-computer-science', 'Students can pursue concentrations in Advanced Systems or Software Development.', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('8-20261114', 'f4', 'requirement', 'Culminating experience', 'Students finish with a comprehensive exam or a thesis research project.', 'https://www.csulb.edu/hung-family-college-of-engineering/master-of-science-computer-science', 'Complete your graduate degree with a comprehensive exam or thesis research project.', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('8-20261114', 'f5', 'requirement', 'Bachelor''s degree and GPA', 'MSCS admissions: bachelor''s in computer engineering or computer science, or sufficient background, with a minimum 2.7 GPA in the last 60 semester or 90 quarter upper-division major units.', 'https://www.csulb.edu/hung-family-college-of-engineering/mscs-admissions', 'Hold a bachelor''s degree in computer engineering or computer science or have sufficient background in computer engineering or computer science from a college or university with a minimum grade point average (GPA) of 2.7 in the last 60 semester or 90 quarter upper-division major units attempted.', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('8-20261114', 'f6', 'requirement', 'University graduate admission requirements', 'The MSCS admissions page also requires applicants to satisfy university requirements for graduate admission.', 'https://www.csulb.edu/hung-family-college-of-engineering/mscs-admissions', 'Satisfy university requirements for graduate admission', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('8-20261114', 'f7', 'requirement', 'University minimum GPA options (university-wide)', 'University-wide graduate standing page: a baccalaureate with a cumulative GPA of at least 2.5, with no rounding. This is a university rule, not an MSCS-only rule.', 'https://www.csulb.edu/admissions/graduate-programs-admission-eligibility', 'Hold a baccalaureate degree with a cumulative GPA of at least 2.5. (No Rounding)', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('8-20261114', 'f8', 'deadline', 'University master''s application latest dates (not MSCS-specific)', 'University Key Dates page: master''s program deadlines vary by program. This is a university-wide latest-date rule, not an MSCS-only deadline.', 'https://www.csulb.edu/enrollment-services/key-dates-and-deadlines', 'Master’s programs and certificates application deadline', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('8-20261114', 'f9', 'deadline', 'Spring 2027 master''s latest date (university-wide)', 'University-wide latest date for master''s applications for Spring 2027 admission: no later than Nov. 1, 2026; the page says dates vary by program.', 'https://www.csulb.edu/enrollment-services/key-dates-and-deadlines', 'Varies by program (no later than Nov. 1, 2026)', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('8-20261114', 'f10', 'deadline', 'Fall 2027 master''s latest date (university-wide)', 'University-wide latest date for master''s applications for Fall 2027 admission: no later than June 1, 2027; the page says dates vary by program.', 'https://www.csulb.edu/enrollment-services/key-dates-and-deadlines', 'Varies by program (no later than June 1, 2027)', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('8-20261114', 'f11', 'overview', 'Department faculty research areas (department-wide)', 'CECS department page (not MSCS-specific): faculty research areas include data science, AI, cybersecurity, software engineering, IoT, and embedded systems.', 'https://www.csulb.edu/college-of-engineering/computer-engineering-computer-science', 'Our faculty are actively involved in advanced research across areas such as data science (with various applications including health), artificial intelligence, cybersecurity, software engineering, internet of things, embedded systems, and more.', '2026-11-14T07:29:27.152108Z');
