INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('8-20261114', 'f37', 'faculty', 'Shadnaz Asgari', 'CECS chair; profile states research integrating AI, signal processing, and computational modeling in clinical and biomedical contexts.', 'https://www.csulb.edu/college-of-engineering/computer-engineering-computer-science/page/dr-shadnaz-asgari', 'Dr. Asgari’s research integrates artificial intelligence, signal processing, and computational modeling to solve problems in clinical and biomedical contexts.', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('8-20261114', 'f38', 'faculty', 'Todd Ebert', 'Profile: research interests in constraint programming.', 'https://www.csulb.edu/college-of-engineering/computer-engineering-computer-science/page/dr-todd-ebert', 'research interests lie in constraint programming, including high-level languages for stating constraint problems, and robust algorithms for solving them.', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('8-20261114', 'f39', 'faculty', 'Bo Fu', 'Profile: research intersects Web Semantics, Human Data Interaction, and Visual Analytics.', 'https://www.csulb.edu/college-of-engineering/computer-engineering-computer-science/page/dr-bo-fu', 'Dr. Fu’s research intersects Web Semantics, Human Data Interaction, and Visual Analytics.', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('8-20261114', 'f40', 'faculty', 'Amir Ghasemkhani', 'Profile: research interests in AI privacy and security for cyber-physical system applications.', 'https://www.csulb.edu/college-of-engineering/computer-engineering-computer-science/page/dr-amir-ghasemkhani', 'research interests revolve around AI privacy and security for cyber physical system (CPS) applications.', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('8-20261114', 'f41', 'faculty', 'Darin Goldstein', 'Profile: interests include algorithms and data structures, games, distributed computation, and computational complexity.', 'https://www.csulb.edu/college-of-engineering/computer-engineering-computer-science/page/dr-darin-goldstein', 'Dr. Goldstein''s interests include algorithms and data structures, games, distributed computation, computational complexity', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('8-20261114', 'f42', 'faculty', 'Min He', 'Profile: research interests include embedded systems, hardware/software codesign, software engineering for embedded systems, parallel algorithms, and optical interconnection networks.', 'https://www.csulb.edu/college-of-engineering/computer-engineering-computer-science/page/dr-min-he', 'research interests include embedded systems, hardware/software codesign for embedded systems, software engineering for embedded systems, parallel algorithms and models, and optical interconnection networks.', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('8-20261114', 'f43', 'faculty', 'Tracy Bradley Maples', 'Profile: research interests in computer networking and modeling and simulation.', 'https://www.csulb.edu/college-of-engineering/computer-engineering-computer-science/page/dr-tracy-bradley-maples', 'research interests lie in the areas of computer networking, modeling and simulation.', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('8-20261114', 'f44', 'faculty', 'Jelena Trajkovic', 'Profile: research interests include multicore embedded systems, pervasive computing, and IoT for critical biomedical and control applications.', 'https://www.csulb.edu/college-of-engineering/computer-engineering-computer-science/page/dr-jelena-trajkovic', 'research interests include multicore embedded systems, pervasive computing, and Internet of Things technologies for critical biomedical and control applications.', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('8-20261114', 'f45', 'faculty', 'Hossein Sayadi', 'Profile: research interests span hardware security, AI and machine learning, cybersecurity, computer architecture, cyber-physical systems, and CS education.', 'https://www.csulb.edu/college-of-engineering/computer-engineering-computer-science/page/dr-hossein-sayadi', 'His research interests span hardware security, AI and machine learning, cybersecurity, computer architecture, cyber-physical systems, and computer science education.', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('8-20261114', 'f46', 'faculty', 'Shabnam Sodagari', 'Graduate advisor. Profile notes teaching in information security, quantum computing, and machine learning.', 'https://www.csulb.edu/college-of-engineering/computer-engineering-computer-science/page/dr-shabnam-sodagari', 'She has taught courses on information security, quantum computing, and machine learning.', '2026-11-14T07:29:27.152108Z');
