INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('8-20261114', 'f48', 'faculty', 'Michael Hoffman', '', 'https://www.csulb.edu/college-of-engineering/computer-engineering-computer-science/page/dr-michael-hoffman', 'Dr. Michael Hoffman', '2026-11-14T07:30:30.817Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('8-20261114', 'f49', 'faculty', 'Amin Rezaei', 'Profile lists research interests in hardware security, machine learning, and computer architecture.', 'https://www.csulb.edu/college-of-engineering/computer-engineering-computer-science/page/dr-amin-rezaei', 'Hardware Security', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('8-20261114', 'f50', 'faculty', 'Wenlu Zhang', '', 'https://www.csulb.edu/college-of-engineering/computer-engineering-computer-science/page/dr-wenlu-zhang', 'Dr. Wenlu Zhang', '2026-11-14T07:30:30.817Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('8-20261114', 'f51', 'faculty', 'Forouzan Golshani', 'Profile emphasizes career honors; it does not state a compact current research-area sentence.', 'https://www.csulb.edu/college-of-engineering/computer-engineering-computer-science/page/dr-forouzan-golshani', 'Forouzan Golshani is a Fellow of the National Academy of Inventors, a Life Time Fellow of IEEE and a Fellow of AAIA.', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('8-20261114', 'f52', 'overview', 'Catalog heading', 'The 2026-2027 University Catalog program heading is Computer Science, M.S.', 'https://catalog.csulb.edu/preview_program.php?catoid=12&poid=6290', 'Computer Science, M.S.', '2026-11-14T07:30:30.817Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('8-20261114', 'f53', 'overview', 'Program mission', 'The catalog describes a graduate program meant to prepare leaders in industry and also students who later pursue advanced degrees, with advanced courses in software and hardware analysis and design.', 'https://catalog.csulb.edu/preview_program.php?catoid=12&poid=6290', 'The mission of the graduate program in Computer Science at CSULB is to provide a high-quality educational experience and the technical specialization required to become successful leaders in industry.', '2026-11-14T07:30:30.817Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('8-20261114', 'f54', 'requirement', 'Thesis or comprehensive examination', 'Students may finish with a thesis or a comprehensive examination.', 'https://catalog.csulb.edu/preview_program.php?catoid=12&poid=6290', 'The students may choose to do a thesis or take a comprehensive examination as the culmination of their program.', '2026-11-14T07:30:30.817Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('8-20261114', 'f55', 'requirement', 'Admission degree background', 'Applicants need a bachelor''s degree in computer engineering or computer science, or sufficient background in those fields, from a college or university.', 'https://catalog.csulb.edu/preview_program.php?catoid=12&poid=6290', 'To be considered for admission the graduate applicant must have earned a bachelor''s degree in computer engineering, computer science or sufficient background in computer engineering or computer science from a college or university', '2026-11-14T07:30:30.817Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('8-20261114', 'f56', 'requirement', 'Admission GPA of 2.7 in last 60 semester units', 'The minimum GPA is 2.7 in the last 60 semester or 90 quarter upper-division major units attempted.', 'https://catalog.csulb.edu/preview_program.php?catoid=12&poid=6290', 'a minimum grade point average (GPA) of 2.7 in the last 60 semester or 90 quarter upper division major units attempted.', '2026-11-14T07:30:30.817Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('8-20261114', 'f57', 'requirement', 'Apply through Cal State Apply, not the department', 'Applications go through Cal State Apply; the page says not to send an application to the department. International students also apply at Cal State Apply.', 'https://catalog.csulb.edu/preview_program.php?catoid=12&poid=6290', 'The student should apply online at www.calstate.edu/apply . Do not send an application to the Department.', '2026-11-14T07:30:30.817Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('8-20261114', 'f58', 'requirement', 'Remove deficiencies before graduate-level courses', 'All deficiencies must be removed before a student attempts graduate-level courses.', 'https://catalog.csulb.edu/preview_program.php?catoid=12&poid=6290', 'All deficiencies must be removed before attempting graduate-level courses.', '2026-11-14T07:30:30.817Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('8-20261114', 'f59', 'requirement', 'Advancement to candidacy: deficiencies and overall GPA', 'Students applying for advancement to candidacy must have completed all undergraduate deficiencies with grades of C or better and have an overall GPA of 3.0.', 'https://catalog.csulb.edu/preview_program.php?catoid=12&poid=6290', 'Students applying for advancement to candidacy must: have completed all undergraduate deficiencies with grades of "C" or better; have attained an overall grade point average (GPA) of 3.0;', '2026-11-14T07:30:30.817Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('8-20261114', 'f60', 'requirement', 'Advancement to candidacy: 9 units and advisor approval', 'They must also complete at least 9 units of required degree-applicable courses with a 3.0 GPA in those units, and have a plan of study approved by the CECS department graduate advisor.', 'https://catalog.csulb.edu/preview_program.php?catoid=12&poid=6290', 'have completed at least 9 units of required courses applicable to the degree with a GPA of at least 3.0 for the completed units; and have their plans of studies approved by the CECS department graduate advisor.', '2026-11-14T07:30:30.817Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('8-20261114', 'f61', 'requirement', 'Degree unit total', 'The degree requires 30 units.', 'https://catalog.csulb.edu/preview_program.php?catoid=12&poid=6290', 'Degree Requirements (30 units)', '2026-11-14T07:30:30.817Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('8-20261114', 'f62', 'requirement', 'First-semester plan of study', 'Students must meet the Graduate Program Adviser at the start of the first semester to make a tentative plan of study. The page also says a detailed required-and-elective list is kept on the Graduate Program website.', 'https://catalog.csulb.edu/preview_program.php?catoid=12&poid=6290', 'Students must meet with the Graduate Program Adviser at the beginning of their first semester to create a tentative plan of study.', '2026-11-14T07:30:30.817Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('8-20261114', 'f63', 'requirement', 'Culminating options and 400-level cap', 'Students must choose the Thesis Option or the Comprehensive Exam Option. At most 9 units of 400-level coursework may count toward the degree.', 'https://catalog.csulb.edu/preview_program.php?catoid=12&poid=6290', 'As a culminating activity, students must elect either the Thesis Option or the Comprehensive Exam Option. A maximum of 9 units of 400-level coursework may be applied toward the degree.', '2026-11-14T07:30:30.817Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('8-20261114', 'f64', 'requirement', 'Comprehensive exam option unit split', 'The exam option requires 30 graduate hours in computer science, a passing comprehensive exam, 15 units of required core courses, and 15 units of allowed electives, with no more than 9 units from 400-level courses.', 'https://catalog.csulb.edu/preview_program.php?catoid=12&poid=6290', 'Student must complete 30 graduate hours credit in computer science and pass the comprehensive exam. 15 units of required core courses', '2026-11-14T07:30:30.817Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('8-20261114', 'f65', 'requirement', 'Exam-option elective units', 'Under the comprehensive exam option, students take 15 units from the allowed electives, with no more than 9 units from 400-level courses.', 'https://catalog.csulb.edu/preview_program.php?catoid=12&poid=6290', '15 units from allowed electives (No more than 9 units may be from the 400 level courses.)', '2026-11-14T07:30:30.817Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('8-20261114', 'f66', 'requirement', 'Comprehensive exam covered courses', 'The comprehensive exam covers CECS 524, CECS 528, and CECS 543. The page does not list CECS 530 or CECS 558 among the covered courses, even though those two are in the required core.', 'https://catalog.csulb.edu/preview_program.php?catoid=12&poid=6290', 'Comprehensive examination covering the following required courses: CECS 524 - Advanced Topics in Programming Languages (3 units) CECS 528 - Advanced Analysis of Algorithms (3 units) CECS 543 - Advanced Software Engineering (3 units)', '2026-11-14T07:30:30.817Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('8-20261114', 'f67', 'requirement', 'Thesis option unit split', 'The thesis option requires 15 units of required courses, 9 units of allowed electives (no more than 9 units from 400-level courses), and 6 units of research and thesis.', 'https://catalog.csulb.edu/preview_program.php?catoid=12&poid=6290', '15 units of required courses', '2026-11-14T07:30:30.817Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('8-20261114', 'f68', 'requirement', 'Thesis-option elective units', 'Under the thesis option, students take 9 units from allowed electives, with no more than 9 units from 400-level courses.', 'https://catalog.csulb.edu/preview_program.php?catoid=12&poid=6290', '9 units from allowed electives (No more than 9 units may be from the 400 level courses.);', '2026-11-14T07:30:30.817Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('8-20261114', 'f69', 'requirement', 'Thesis research and report', 'The thesis option includes 6 units of research and thesis with a written report and oral presentation approved by the thesis committee. At least 3 of those units must be CECS 698; the remaining 3 units may be CECS 697 or CECS 698.', 'https://catalog.csulb.edu/preview_program.php?catoid=12&poid=6290', '6 units of research and thesis with written report and oral presentation approved by the thesis committee.', '2026-11-14T07:30:30.817Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('8-20261114', 'f70', 'requirement', 'Thesis minimum from CECS 698', 'At least 3 of the 6 thesis-option research units must be taken from CECS 698 Thesis or Industrial Project.', 'https://catalog.csulb.edu/preview_program.php?catoid=12&poid=6290', 'At least 3 units must be taken from the following course CECS 698 - Thesis or Industrial Project (3-6 units)', '2026-11-14T07:30:30.817Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('8-20261114', 'f71', 'requirement', 'Thesis remaining 3 units', 'The remaining 3 thesis research units may be CECS 697 Directed Research or CECS 698 Thesis or Industrial Project.', 'https://catalog.csulb.edu/preview_program.php?catoid=12&poid=6290', 'Remaining 3 units may be taken from either of the following courses CECS 697 - Directed Research (1-3 units) CECS 698 - Thesis or Industrial Project (3-6 units)', '2026-11-14T07:30:30.817Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('8-20261114', 'f72', 'course', 'CECS 524', 'Required 3-unit core course for both culminating options; also covered on the comprehensive exam.', 'https://catalog.csulb.edu/preview_program.php?catoid=12&poid=6290', 'CECS 524 - Advanced Topics in Programming Languages (3 units)', '2026-11-14T07:30:30.817Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('8-20261114', 'f73', 'course', 'CECS 528', 'Required 3-unit core course for both culminating options; also covered on the comprehensive exam.', 'https://catalog.csulb.edu/preview_program.php?catoid=12&poid=6290', 'CECS 528 - Advanced Analysis of Algorithms (3 units)', '2026-11-14T07:30:30.817Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('8-20261114', 'f74', 'course', 'CECS 530', 'Required 3-unit core course for both culminating options.', 'https://catalog.csulb.edu/preview_program.php?catoid=12&poid=6290', 'CECS 530 - Advanced Computer Architecture I (3 units)', '2026-11-14T07:30:30.817Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('8-20261114', 'f75', 'course', 'CECS 543', 'Required 3-unit core course for both culminating options; also covered on the comprehensive exam.', 'https://catalog.csulb.edu/preview_program.php?catoid=12&poid=6290', 'CECS 543 - Advanced Software Engineering (3 units)', '2026-11-14T07:30:30.817Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('8-20261114', 'f76', 'course', 'CECS 558', 'Required 3-unit core course for both culminating options.', 'https://catalog.csulb.edu/preview_program.php?catoid=12&poid=6290', 'CECS 558 - Deep Learning (3 units)', '2026-11-14T07:30:30.817Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('8-20261114', 'f77', 'course', 'CECS 698', 'Thesis or Industrial Project, 3-6 units; at least 3 units are required in the thesis option.', 'https://catalog.csulb.edu/preview_program.php?catoid=12&poid=6290', 'CECS 698 - Thesis or Industrial Project (3-6 units)', '2026-11-14T07:30:30.817Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('8-20261114', 'f78', 'course', 'CECS 697', 'Directed Research, 1-3 units; listed among exam-option electives and as a way to finish the remaining 3 thesis units.', 'https://catalog.csulb.edu/preview_program.php?catoid=12&poid=6290', 'CECS 697 - Directed Research (1-3 units)', '2026-11-14T07:30:30.817Z');
